export const SCENARIOS: Scenario[] = [
  { id: 1, name: 'single-file fix', task: 'The order total ignores the discount percentage. Fix it so the tests pass.', relevant: ['src/orders/orderService.js'] },
  { id: 2, name: 'multi-file change', task: 'Add an optional status filter to the order list: listOrders should accept a status and the orders HTTP handler should read it from the ?status= query parameter. Keep the tests passing.', relevant: ['src/orders/orderService.js', 'src/orders/orderHandler.js'] },
  { id: 3, name: 'similar module names', task: 'Reordering a past purchase loses the item quantities (always 1). Fix the reorder logic so the tests pass.', relevant: ['src/reorder/reorderService.js'] },
  { id: 4, name: 'trivial, file named', task: 'Rename the function formatPrice to formatMoney in src/lib/money.js and update all usages; keep the tests passing.', relevant: ['src/lib/money.js'] },
];

export function fixture(scenario: number): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lumina-ctx-bench-'));
  const w = (f: string, c: string) => { fs.mkdirSync(path.dirname(path.join(dir, f)), { recursive: true }); fs.writeFileSync(path.join(dir, f), c); };
  w('package.json', JSON.stringify({ name: 'shop-api', type: 'module', scripts: { test: 'node --test' } }, null, 2));
  w('src/lib/money.js', "export function formatPrice(cents) {
  return `$${(cents / 100).toFixed(2)}`;
}
");
  w('src/lib/http.js', 'export function json(res, status, body) {
  return { status, body };
}
');
  for (const m of MODULES) {
    const C = m[0].toUpperCase() + m.slice(1);
    w(`src/${m}/${m}Service.js`, `const store = [];
export function list${C}() {
  return store.slice();
}
export function add${C}(x) {
  store.push(x);
  return x;
}
`);
    w(`src/${m}/${m}Handler.js`, `import { json } from '../lib/http.js';
import { list${C} } from './${m}Service.js';
export function handleList${C}(req) {
  return json(null, 200, list${C}());
}
`);
    w(`test/${m}.test.js`, `import test from 'node:test';
import assert from 'node:assert/strict';
import { add${C}, list${C} } from '../src/${m}/${m}Service.js';
test('${m}', () => { add${C}({ id: 1 }); assert.equal(list${C}().length, 1); });
`);
  }
  w('src/orders/orderService.js', `import { formatPrice } from '../lib/money.js';
const orders = [
  { id: 1, status: 'paid', items: [{ price: 1000, qty: 2 }], discount: 10 },
  { id: 2, status: 'pending', items: [{ price: 500, qty: 1 }], discount: 0 },
];
export function listOrders() {
  return orders.slice();
}
export function orderTotal(order) {
  return order.items.reduce((s, i) => s + i.price * i.qty, 0)${scenario === 1 ? '' : ' * (1 - order.discount / 100)'};
}
export function describeOrder(order) {
  return \`#\${order.id} \${formatPrice(orderTotal(order))}\`;
}
`);
  w('src/orders/orderHandler.js', "import { json } from '../lib/http.js';
import { listOrders } from './orderService.js';
export function handleListOrders(req) {
  return json(null, 200, listOrders());
}
");
  w('test/orders.test.js', "import test from 'node:test';
import assert from 'node:assert/strict';
import { listOrders, orderTotal } from '../src/orders/orderService.js';
test('total applies discount', () => assert.equal(orderTotal(listOrders()[0]), 1800));
test('lists orders', () => assert.equal(listOrders().length, 2));
");
  w('src/reorder/reorderService.js', `export function reorder(pastOrder) {
  return { items: pastOrder.items.map((i) => ({ price: i.price, qty: ${scenario === 3 ? '1' : 'i.qty'} })) };
}
`);
  w('test/reorder.test.js', "import test from 'node:test';
import assert from 'node:assert/strict';
import { reorder } from '../src/reorder/reorderService.js';
test('keeps quantities', () => assert.equal(reorder({ items: [{ price: 1, qty: 3 }] }).items[0].qty, 3));
");
  w('test/money.test.js', "import test from 'node:test';
import assert from 'node:assert/strict';
import * as money from '../src/lib/money.js';
test('formats', () => assert.equal((money.formatMoney ?? money.formatPrice)(1234), '$12.34'));
");
  w('README.md', '# shop-api

Small order management API used for benchmarks.
');
  execFileSync('git', ['init', '-q'], { cwd: dir });
  execFileSync('git', ['add', '-A'], { cwd: dir });
  return dir;
}

async function runOne(s: Scenario, variant: Run['variant']): Promise<Run> {
  const dir = fixture(s.id);
  const cfg = ConfigSchema.parse({ analytics: { enabled: false } });
  const rt = route({ task: s.task, repository: dir }, cfg, loadCatalog());
  const sel = { model: rt.model, effort: rt.reasoning_effort };
  const client = new AppServerClient({ cwd: dir });
  await client.start();
  const chat = new Chat(client, { cwd: dir, onDelta: () => undefined, policy: { approvalPolicy: 'never', sandbox: 'workspace-write' } });
  try {
    const t0 = Date.now();
    let hintFiles: string[] = [];
    let retrievalMs = 0;
    if (variant === 'B') {
      process.env.SMART_CODEX_HOME = fs.mkdtempSync(path.join(os.tmpdir(), 'lumina-ctx-home-'));
      const r = await new Retriever(dir, cfg.retrieval).retrieve(s.task);
      retrievalMs = r.ms;
      if (r.block) { chat.queueContext(r.block); hintFiles = r.hints.map((h) => h.path); }
    }
    const res = await chat.send(s.task, sel);
    const ms = Date.now() - t0;
    const files = execFileSync('git', ['ls-files'], { cwd: dir, encoding: 'utf8' }).split('\n').filter((f) => f.startsWith('src/'));
    const cmds = (res.items ?? []).filter((i) => i.type === 'commandExecution').map((i) => i.command ?? '');
    // files Codex reported reading (commandActions), plus files named in other commands (an approximation, e.g. rg/grep)
    const reported = filesRead(res.items ?? [], fs.realpathSync(dir));
    const inspected = files.filter((f) => reported.includes(f) || cmds.some((c) => c.includes(f) || c.includes(path.basename(f))));
    let testsPass = false;
    try { execFileSync('node', ['--test'], { cwd: dir, stdio: 'ignore', timeout: 60000 }); testsPass = true; } catch { /* failed */ }
    return { scenario: s.id, variant, usage: res.usage, ms, retrievalMs, hintFiles, relevantFound: s.relevant.filter((f) => hintFiles.includes(f)).length, inspected, unnecessary: inspected.filter((f) => !s.relevant.includes(f)), commands: cmds.length, status: res.status, testsPass };
  } finally { await client.close(); fs.rmSync(dir, { recursive: true, force: true }); }
}

async function main(): Promise<void> {
if (process.env.LUMINA_BENCH_DRY) {
  const { ConfigSchema: C } = await import('../src/smart-codex/config.js');
  for (const s of SCENARIOS) { const dir = fixture(s.id); const r = await new Retriever(dir, C.parse({}).retrieval).retrieve(s.task); console.log(s.id, r.skipped ?? '', r.ms + 'ms\n' + (r.block ?? '')); fs.rmSync(dir, { recursive: true, force: true }); }
  return;
}
const args = process.argv.slice(2);
const pick = (flag: string, d: string) => { const i = args.indexOf(flag); return i >= 0 ? args[i + 1] : d; };
const ids = pick('--scenarios', '1,2,3,4').split(',').map(Number);
const repeat = Number(pick('--repeat', '1'));
const runs: Run[] = [];
for (let k = 0; k < repeat; k++) for (const s of SCENARIOS.filter((x) => ids.includes(x.id))) for (const v of ['A', 'B'] as const) {
  process.stderr.write(`scenario ${s.id} (${s.name}) · ${v} · run ${k + 1}…\n`);
  runs.push(await runOne(s, v));
}
const rows = runs.map((r) => {
  const s = SCENARIOS.find((x) => x.id === r.scenario)!;
  const tok = r.usage ? `${r.usage.inputTokens} / ${r.usage.cachedInputTokens} / ${r.usage.outputTokens}` : 'not reported';
  return `| ${r.scenario}. ${s.name} | ${r.variant} | ${tok} | ${Math.round(r.ms / 1000)}s | ${r.retrievalMs}ms | ${r.variant === 'B' ? `${r.relevantFound}/${s.relevant.length} (${r.hintFiles.length} hinted)` : '-'} | ${r.commands} | ${r.inspected.length} | ${r.unnecessary.length} | ${r.status}, tests ${r.testsPass ? 'pass' : 'FAIL'} |`;
});
console.log(['| scenario | variant | tokens in / cached / out | time | retrieval | relevant hinted | commands | files inspected | unnecessary | result |', '|---|---|---|---|---|---|---|---|---|---|', ...rows].join('\n'));
const file = path.join('bench', 'results', `context-real-${ids.join('_')}-${new Date().toISOString().slice(0, 10)}.json`);
fs.writeFileSync(file, JSON.stringify({ date: new Date().toISOString(), runs }, null, 2));
console.log(`\nwritten: ${file}`);
}

const rows = runs.map((r) => {
  const s = SCENARIOS.find((x) => x.id === r.scenario)!;
  const tok = r.usage ? `${r.usage.inputTokens} / ${r.usage.cachedInputTokens} / ${r.usage.outputTokens}` : 'not reported';
  return `| ${r.scenario}. ${s.name} | ${r.variant} | ${tok} | ${Math.round(r.ms / 1000)}s | ${r.retrievalMs}ms | ${r.variant === 'B' ? `${r.relevantFound}/${s.relevant.length} (${r.hintFiles.length} hinted)` : '-'} | ${r.commands} | ${r.inspected.length} | ${r.unnecessary.length} | ${r.status}, tests ${r.testsPass ? 'pass' : 'FAIL'} |`;
});

const rows = runs.map((r) => {
  const s = SCENARIOS.find((x) => x.id === r.scenario)!;
  const tok = r.usage ? `${r.usage.inputTokens} / ${r.usage.cachedInputTokens} / ${r.usage.outputTokens}` : 'not reported';
  return `| ${r.scenario}. ${s.name} | ${r.variant} | ${tok} | ${Math.round(r.ms / 1000)}s | ${r.retrievalMs}ms | ${r.variant === 'B' ? `${r.relevantFound}/${s.relevant.length} (${r.hintFiles.length} hinted)` : '-'} | ${r.commands} | ${r.inspected.length} | ${r.unnecessary.length} | ${r.status}, tests ${r.testsPass ? 'pass' : 'FAIL'} |`;
});

export interface Route {
  tier: Tier;
  complexity_score: number;
  confidence: number;
  risk: 'low' | 'medium' | 'high';
  model: string;
  reasoning_effort: string;
  agent_strategy: 'single' | 'single_then_review' | 'parallel';
  relevant_files: string[];
  require_review: boolean;
  escalation_allowed: boolean;
  reason: string;
}

const LEX = {
  sensitive: /\b(payments?|billing|checkout|stripe|paypal|refunds?|invoices?|ledger|financial|transactions?|auth|authentication|authorization|authori[sz]e|login|passwords?|credentials?|jwt|oauth|sso|rbac|permissions?|security|vulnerabilit\w*|cve|xss|csrf|sql injection|secrets?|encrypt\w*|migrations?|drop table|production data|data integrity|pii|(?:refresh|access|api|auth|bearer|csrf) tokens?)\b/gi,
  hard: /\b(refactor\w*|architect\w*|redesign|restructur\w*|decoupl\w*|monolith|concurren\w*|race conditions?|deadlocks?|distributed|memory leaks?|intermittent|complex|multi-?file|performance|async|rewrite|migrate)\b/gi,
  normal: /\b(add|implement|create|build|endpoint|api|crud|component|feature|service|fix|bug|tests?|unit|validation|route|handler|hook)\b/gi,
  // trivial operations (cosmetic/textual)
  fast: /\b(renam\w*|typos?|spelling|text|copy|label|wording|colou?rs?|styl\w*|css|padding|margin|spacing|font|comments?|readme|docs?|documentation|changelog|translations?|tooltips?|placeholders?|headings?|bump|version|icon)\b/gi,
  // surfaces where a trivial operation cannot change security behavior
  safeObject: /\b(page|button|label|text|copy|readme|docs?|documentation|comments?|changelog|tooltips?|placeholders?|banner|icon|colou?rs?|css|style|styling|ui|layout|headings?|titles?|translations?|wording|spacing|font)\b/i,
  // words showing real code logic is touched
  logic: /\b(implement\w*|verif\w*|validat\w*|middleware|handlers?|flow|rotat\w*|signatures?|sign(ing)?|hash\w*|schema|quer(y|ies)|endpoints?|api|logic|guards?|polic(y|ies)|webhooks?|sessions?|refactor\w*|rewrite|encrypt\w*)\b/i,
  feature: /\b(crud|components?|features?|services?|routes?|hooks?|tests?|unit)\b/i,
  scope: /\b(all|every|entire|whole|across|multiple|throughout|codebase)\b/gi,
  readOnly: /^\s*(explain|describe|summari[sz]e|list|show|where|how|why|what)\b/i,
  modify: /\b(implement|fix|add|change|update|refactor|rewrite|remove|delete|create|build|migrate|rotate|replace|patch)\b/i,
};

const COMMIT_MSG = [
  / (feat|fix|chore|docs|refactor|test|perf|build|ci|style|revert)(\([^)
]*\))?!?:[^
]*/gi, // conventional-commit subject, to end of line
  /(?:-m|--message)[ =]*(?:"[^"
]*"|'[^'
]*'|\S+)/gi, // git commit -m "..."
  / (?:dengan|pakai|with|using|gunakan|use)\s+(?:(?:the|this|ini)\s+)?(?:commit\s+)?(?:message|pesan) [^
]*/gi, // "with message <free text>"
  / (?:untuk|for|as)\s+(?:the\s+)?(?:commit\s+)?(?:message|pesan) [^
]*/gi,
];

export function gitIntent(task: string): GitIntent | undefined {
  let s = task;
  for (const re of COMMIT_MSG) s = s.replace(re, ' ');
  if (GIT_DANGEROUS.test(s)) return 'dangerous';
  if (GIT_CONFLICT.test(s)) return 'conflict';
  // a pure git operation: git verbs present, and no work verbs left (after dropping "git add")
  return GIT_OP.test(s) && !GIT_WORK.test(s.replace(/\bgit\s+add\b/gi, 'git')) ? 'simple' : undefined;
}

export function route(input: RouteInput, cfg: RouterConfig, catalog: ModelInfo[] = loadCatalog()): Route {
  const text = `${input.task}\n${input.context ?? ''}`.slice(0, 20000);
  const h = {
    sensitive: count(LEX.sensitive, text), hard: count(LEX.hard, text), normal: count(LEX.normal, text),
    fast: count(LEX.fast, text), scope: count(LEX.scope, text),
  };
  const o = cfg.optimization;
  const git = gitIntent(input.task);
  // git ops need no file hints (and message words would only pull in unrelated files)
  const found = o.minimal_context && git !== 'simple'
    ? discover(input.task, path.resolve(input.repository ?? process.cwd()), { maxFiles: o.max_context_files, maxScanned: o.max_scanned_files, maxDepth: o.max_analysis_depth, maxReadBytes: o.max_file_read_bytes })
    : { files: [], confident: false, components: 0 };
  const files = found.files;
  const injection = INJECTION.test(text);
  const words = input.task.trim().split(/\s+/).length;
  const reasons: string[] = [];

  // --- intent: judge the operation and the affected code, not just the domain words ---
  const logic = LEX.logic.test(input.task);
  const trivialOp = h.fast > 0 && !logic && h.hard === 0 && h.scope === 0 && !LEX.feature.test(input.task);
  let sensitive = h.sensitive > 0;
  if (sensitive && trivialOp && LEX.safeObject.test(input.task) && !logic) {
    sensitive = false;
    reasons.push('sensitive domain mentioned, but change is cosmetic/documentation only');
  } else if (sensitive && LEX.readOnly.test(input.task) && !LEX.modify.test(input.task)) {
    sensitive = false;
    h.normal = Math.max(h.normal, 1);
    reasons.push('read-only question about a sensitive domain');
  }

  if (git === 'simple') { sensitive = false; reasons.push('git operation; commit message is metadata'); }
  else if (git === 'dangerous') { sensitive = true; reasons.push('destructive/history-rewriting git operation'); }

  // base complexity excludes sensitivity; dependency spread adds to it
  const spread = found.confident && found.components >= 3 ? 1 : 0;
  const base = Math.max(0, Math.min(10, 2 + Math.min(h.normal, 3) + 3 * Math.min(h.hard, 2) + 2 * Math.min(h.scope, 1)
    - Math.min(h.fast, 2) + (files.length > 5 && found.confident ? 1 : 0) + spread + (words > 60 ? 1 : 0)));
  const score = Math.min(10, base + (sensitive ? 4 : 0));

  let tier: Tier;
  if (sensitive) { tier = 'critical'; reasons.push('modifies security/payment/data-integrity logic (or intent unclear)'); }
  else if ((base >= 7 && h.hard + h.scope + spread > 0) || (h.hard > 0 && base >= 5)) { tier = 'hard'; reasons.push('multi-factor complexity'); }
  else if (git === 'conflict') { tier = 'hard'; reasons.push('git conflict resolution'); }
  else if (git === 'simple' || trivialOp) { tier = 'fast'; reasons.push('trivial edit'); }
  else if (base >= 3 && h.normal + h.hard + h.scope > 0) { tier = 'normal'; reasons.push('standard implementation work'); }
  else { tier = cfg.routing.default_tier; reasons.push('ambiguous; conservative default'); }
  if (spread && tier !== 'critical') reasons.push(`touches ${found.components} components`);

  const hits = h.sensitive + h.hard + h.normal + h.fast;
  let confidence = hits === 0 ? 0.4 : Math.min(0.95, 0.6 + 0.1 * Math.min(hits, 3));
  if (h.fast > 0 && h.hard > 0) confidence -= 0.15;
  if (found.confident) confidence += 0.05;
  if (git) confidence = Math.max(confidence, 0.85);
  if (injection) {
    confidence = Math.min(confidence, 0.4);
    if (TIERS.indexOf(tier) < TIERS.indexOf('normal')) tier = 'normal';
    reasons.push('routing-override language in task ignored (treated as data)');
  }
  // low confidence never lands on the cheapest tier
  if (confidence < 0.5 && tier === 'fast') tier = 'normal';

  const prefs = input.preferences ?? {};
  if (prefs.tier && TIERS.includes(prefs.tier)) { tier = prefs.tier; reasons.push(`tier override: ${tier}`); }

  // model follows the tier; reasoning is adjusted independently: a trivial operation inside
  // security-sensitive code keeps the strong model but needs less thinking.
  const risk = tier === 'critical' ? 'high' : tier === 'hard' || sensitive ? 'medium' : 'low';
  const simpleCritical = tier === 'critical' && !prefs.tier && git !== 'dangerous' && trivialOp && !logic && h.hard === 0;
  const wantModel = prefs.model ?? cfg.models[tier];
  const wantEffort = prefs.reasoning ?? (simpleCritical ? cfg.reasoning.critical_simple : cfg.reasoning[tier]);
  const resolved = resolveModel(catalog, wantModel, wantEffort, Boolean(prefs.model || prefs.reasoning));
  if (resolved.note) reasons.push(resolved.note);
  if (prefs.reasoning === 'low' && (tier === 'critical' || tier === 'hard')) {
    reasons.push('warning: low reasoning explicitly requested for a high-risk task');
  }

  const parallel = /\b(in parallel|independent(ly)? (modules|services|tasks))\b/i.test(text) && (tier === 'hard' || tier === 'critical');
  const requireReview = tier === 'critical' && score >= 8;
  return {
    tier, complexity_score: score, confidence: Math.round(confidence * 100) / 100, risk,
    model: resolved.model, reasoning_effort: resolved.effort,
    agent_strategy: parallel && cfg.routing.default_agents > 1 ? 'parallel' : requireReview ? 'single_then_review' : 'single',
    relevant_files: files, require_review: requireReview,
    escalation_allowed: cfg.escalation.enabled && !DESTRUCTIVE.test(text),
    reason: reasons.join('; '),
  };
}

const h = {
  sensitive: count(LEX.sensitive, text), hard: count(LEX.hard, text), normal: count(LEX.normal, text),
  fast: count(LEX.fast, text), scope: count(LEX.scope, text),
};

const found = o.minimal_context && git !== 'simple'
  ? discover(input.task, path.resolve(input.repository ?? process.cwd()), { maxFiles: o.max_context_files, maxScanned: o.max_scanned_files, maxDepth: o.max_analysis_depth, maxReadBytes: o.max_file_read_bytes })
  : { files: [], confident: false, components: 0 };

export function explain(r: Route): string {
  return [
    `Tier ${r.tier} (score ${r.complexity_score}/10, confidence ${r.confidence}, risk ${r.risk})`,
    `Model ${r.model} @ ${r.reasoning_effort}; agents: ${r.agent_strategy}; review: ${r.require_review}`,
    `Escalation ${r.escalation_allowed ? 'allowed' : 'disabled'}; files: ${r.relevant_files.length ? r.relevant_files.join(', ') : 'none (Codex discovers)'}`,
    `Why: ${r.reason}`,
  ].join('\n');
}

export interface Stage {
  id: string; type: StageType; title: string; tier: Tier; effort: string; status: StageStatus;
  model?: string; attempts: number; escalation: number; outcome?: string; ms?: number; reason: string;
}

const CUE = {
  design: /\b(architect\w*|design|schema|data model|rbac|permissions?|authori[sz]ation|refresh tokens?|multi-?tenant|migrations?)\b/i,
  tests: /\b(tests?|testing|unit tests?|e2e|coverage|pengujian|tes)\b/i,
  review: /\b(security|secure|review|audit|keamanan|vulnerab\w*)\b/i,
  docs: /\b(docs?|documentation|readme|dokumentasi)\b/i,
};

export function planStages(task: string, route: Route, cfg: RouterConfig): Stage[] {
  const sc = cfg.stages;
  if (!sc.enabled) return [];
  const cues = { design: CUE.design.test(task), tests: CUE.tests.test(task), review: CUE.review.test(task) || route.tier === 'critical', docs: CUE.docs.test(task) };
  const heavy = route.tier === 'hard' || route.tier === 'critical';
  const cueCount = Object.values(cues).filter(Boolean).length;
  if (!heavy && cueCount < 2) return [];
  const types: StageType[] = [];
  if (heavy) types.push('analyze');
  if (cues.design || route.tier === 'critical') types.push('design');
  types.push('implement');
  if (cues.tests || route.tier === 'critical') types.push('test');
  if (cues.review) types.push('review');
  if (cues.docs) types.push('docs');
  // leave room for one inserted fix stage
  for (const d of DROP) if (types.length > Math.max(1, sc.max_stages - 1) && types.includes(d)) types.splice(types.indexOf(d), 1);
  if (types.length < 2) return [];
  return types.map((t) => makeStage(t));
}

export interface ExecutionContext {
  task: string; completed: string[]; current_stage: string; modified_files: string[]; known_issues: string[]; pending: string[]; constraints: string[];
}

export function analyzeStage(items: TurnItem[] = []): { files: string[]; testsFailed: boolean; stuck: boolean; outcome: string; failures: string[] } {
  const files = [...new Set(items.flatMap((i) => i.files ?? []))];
  const tests = items.filter((i) => i.type === 'commandExecution' && i.command && TEST_CMD.test(i.command));
  const last = tests.at(-1);
  const testsFailed = Boolean(last && typeof last.exitCode === 'number' && last.exitCode !== 0);
  const message = items.filter((i) => i.type === 'agentMessage' && i.text).at(-1)?.text ?? '';
  const failures = testsFailed ? [`tests still failing (exit ${last!.exitCode}) after \`${last!.command!.replace(/^\S*sh -lc /, '').slice(0, 80)}\``] : [];
  return { files, testsFailed, stuck: STUCK.test(message), outcome: message.replace(/\s+/g, ' ').trim().slice(0, 160), failures };
}

export interface RoutingLog {
  level: 'info' | 'warn'; event: string; request_id: string; execution_id: string; stage_id?: string; stage_type?: string;
  previous_model?: string | null; selected_model?: string; routing_reason?: string; escalation_level?: number;
  execution_duration_ms?: number; retry_count?: number; switch_count?: number; routing_strategy: 'single' | 'staged'; status?: string; [k: string]: unknown;
}

export function logRouting(entry: RoutingLog, cfg: RouterConfig): void {
  if (!cfg.analytics.enabled) return;
  try {
    fs.mkdirSync(stateDir(), { recursive: true });
    fs.appendFileSync(path.join(stateDir(), 'routing.jsonl'), `${JSON.stringify({ ts: new Date().toISOString(), ...entry })}\n`);
  } catch { /* logging must never break execution */ }
}

export interface StageHooks {
  /** `models` are the models each stage will start on (validated against the catalog). */
  planned(stages: Stage[], models: string[]): void;
  stageStart(stage: Stage, index: number, total: number, sel: Selection, switched?: { from: string; to: string; reason: string }): void;
  stageEnd(stage: Stage, index: number, total: number): void;
  notice(text: string): void;
}

export interface StageDeps {
  cfg: RouterConfig;
  catalog: ModelInfo[];
  /** Runs one turn on the current thread with an explicit model/effort (the real switch). */
  send(prompt: string, sel: Selection, first: boolean): Promise<TurnResult>;
  interrupt(): Promise<unknown>;
  cancelled(): boolean;
  hooks: StageHooks;
  log?: (e: RoutingLog) => void;
  requestId?: string;
}

export class StagedExecution {
  readonly id = `exec_${randomUUID().slice(0, 12)}`;
  readonly ctx: ExecutionContext;
  private switches = 0;
  private escalations = 0;
  private prevModel: string | null = null;

  constructor(private readonly task: string, readonly stages: Stage[], private readonly deps: StageDeps, constraints: string[] = []) {
    this.ctx = { task: task.replace(/\s+/g, ' ').trim().slice(0, 200), completed: [], current_stage: '', modified_files: [], known_issues: [], pending: [], constraints: ['do not redo completed stages', ...constraints] };
  }

  private log(e: Omit<RoutingLog, 'request_id' | 'execution_id' | 'routing_strategy'>): void {
    const entry = { request_id: this.deps.requestId ?? this.id, execution_id: this.id, routing_strategy: 'staged', switch_count: this.switches, ...e } as RoutingLog;
    (this.deps.log ?? ((x) => logRouting(x, this.deps.cfg)))(entry);
  }

  /** Model for a tier, validated against the installed catalog; unavailable models fall back safely. */
  private select(tier: Tier, effort: string): Selection & { note?: string } {
    const want = this.deps.cfg.stages.tiers[tier];
    const r = resolveModel(this.deps.catalog, want, effort, false, this.deps.cfg.stages.tiers.fast);
    return { model: r.model, effort: r.effort, note: r.note };
  }

  private prompt(stage: Stage, i: number, total: number): string {
    this.ctx.current_stage = stage.title;
    this.ctx.pending = this.stages.slice(i + 1).filter((s) => s.status === 'pending').map((s) => s.title);
    const last = i === total - 1 || this.ctx.pending.length === 0;
    const parts = [`[Lumina stage ${i + 1}/${total}: ${stage.title}]`, `Handoff: ${JSON.stringify(this.ctx)}`, `Objective: ${DEF[stage.type].objective}`];
    if (i === 0) parts.push(`User request:\n${this.task}`); // the only time the full request is sent; later stages rely on the thread + handoff
    if (last) parts.push('This is the final stage: finish with a concise summary for the user of everything done across all stages.');
    return parts.join('\n\n');
  }

  async run(): Promise<ExecutionResult> {
    const { cfg, hooks } = this.deps;
    const lim = cfg.stages;
    hooks.planned(this.stages, this.stages.map((s) => this.select(s.tier, s.effort).model ?? ''));
    this.log({ level: 'info', event: 'plan_created', status: `${this.stages.length} stages`, stage_type: this.stages.map((s) => s.type).join('>') });
    let failure: string | undefined;
    let status: ExecutionResult['status'] = 'completed';

    for (let i = 0; i < this.stages.length; i++) {
      const stage = this.stages[i];
      if (this.deps.cancelled()) { status = 'cancelled'; break; }
      stage.status = 'running';
      let tier = stage.tier;
      let effort = stage.effort;
      for (;;) {
        stage.attempts++;
        let sel = this.select(tier, effort);
        let switched: { from: string; to: string; reason: string } | undefined;
        if (this.prevModel && sel.model !== this.prevModel) {
          if (this.switches >= lim.max_switches) { // limit reached: stay on the current model
            this.log({ level: 'warn', event: 'switch_limit_reached', stage_id: stage.id, stage_type: stage.type, selected_model: this.prevModel, routing_reason: `wanted ${sel.model}` });
            sel = { model: this.prevModel, effort: sel.effort };
          } else {
            this.switches++;
            switched = { from: this.prevModel, to: sel.model!, reason: stage.reason };
            this.log({ level: 'info', event: 'model_switched', stage_id: stage.id, stage_type: stage.type, previous_model: this.prevModel, selected_model: sel.model, routing_reason: stage.reason, escalation_level: stage.escalation });
          }
        }
        if (sel.note) this.log({ level: 'warn', event: 'model_fallback', stage_id: stage.id, stage_type: stage.type, selected_model: sel.model, routing_reason: sel.note });
        stage.model = sel.model;
        hooks.stageStart(stage, i, this.stages.length, sel, switched);
        this.log({ level: 'info', event: 'stage_started', stage_id: stage.id, stage_type: stage.type, previous_model: this.prevModel, selected_model: sel.model, routing_reason: stage.reason, escalation_level: stage.escalation, retry_count: stage.attempts - 1 });
        const t0 = Date.now();
        let result: TurnResult;
        try {
          result = await this.withTimeout(this.deps.send(this.prompt(stage, i, this.stages.length), { model: sel.model, effort: sel.effort }, i === 0 && stage.attempts === 1), lim.stage_timeout_ms);
        } catch (e) {
          result = { status: 'failed', error: e instanceof Error ? e.message : String(e) };
        }
        stage.ms = (stage.ms ?? 0) + Date.now() - t0;
        this.prevModel = sel.model ?? this.prevModel;
        const sig = analyzeStage(result.items);
        for (const f of sig.files) if (!this.ctx.modified_files.includes(f)) this.ctx.modified_files.push(f);
        this.ctx.modified_files = this.ctx.modified_files.slice(-30);

        if (result.status === 'interrupted' || this.deps.cancelled()) { stage.status = 'skipped'; stage.outcome = 'cancelled'; status = 'cancelled'; break; }
        if (result.status === 'failed') {
          const kind = classifyFailure(result.error ?? '');
          const rejectedModel = /model/i.test(result.error ?? '') && /(not (supported|available)|unsupported|unknown|invalid)/i.test(result.error ?? '');
          if (rejectedModel && sel.model !== cfg.stages.tiers.fast && stage.attempts <= lim.max_retries) {
            this.log({ level: 'warn', event: 'model_rejected', stage_id: stage.id, stage_type: stage.type, selected_model: sel.model, routing_reason: 'backend rejected model; falling back' });
            tier = 'fast'; continue;
          }
          if (kind === 'coding' && stage.attempts <= lim.max_retries && this.escalations < lim.max_escalations && tier !== 'advanced') {
            tier = TIER_ORDER[TIER_ORDER.indexOf(tier) + 1]; effort = 'high'; stage.escalation++; this.escalations++;
            this.log({ level: 'warn', event: 'escalated', stage_id: stage.id, stage_type: stage.type, selected_model: this.select(tier, effort).model, routing_reason: 'stage failed', escalation_level: stage.escalation, retry_count: stage.attempts });
            hooks.notice(`stage failed; retrying ${stage.title} on a stronger model`);
            continue;
          }
          stage.status = 'failed'; stage.outcome = (result.error ?? 'failed').slice(0, 160);
          failure = `${stage.title} failed${kind !== 'coding' ? ` (${kind})` : ''}: ${stage.outcome}`;
          status = 'failed';
          break;
        }
        stage.status = 'done';
        stage.outcome = sig.outcome;
        this.ctx.completed.push(`${stage.title}: ${sig.outcome || 'done'}`.slice(0, 200));
        if (sig.failures.length) this.ctx.known_issues.push(...sig.failures);
        this.ctx.known_issues = this.ctx.known_issues.slice(-5);
        // Dynamic replanning: insert a fix stage (escalated one tier per consecutive fix) when real problems remain.
        const problem = sig.testsFailed || (sig.stuck && ['implement', 'fix', 'test'].includes(stage.type));
        if (problem) {
          const fixes = this.stages.filter((s) => s.type === 'fix').length;
          const nextTier = TIER_ORDER[Math.min(TIER_ORDER.indexOf(stage.type === 'fix' ? stage.tier : 'fast') + 1, 2)];
          if (fixes < lim.max_retries && this.escalations < lim.max_escalations && this.stages.length < lim.max_stages) {
            const fix = makeStage('fix', nextTier, sig.testsFailed ? 'tests still failing after previous stage' : 'previous stage reported it could not resolve the problem');
            fix.escalation = TIER_ORDER.indexOf(nextTier);
            this.escalations++;
            this.stages.splice(i + 1, 0, fix);
            this.log({ level: 'warn', event: 'escalated', stage_id: fix.id, stage_type: 'fix', selected_model: this.select(nextTier, 'high').model, routing_reason: fix.reason, escalation_level: fix.escalation });
          } else {
            this.log({ level: 'warn', event: 'escalation_limit_reached', stage_id: stage.id, stage_type: stage.type, routing_reason: 'problems remain' });
            if (stage.type === 'fix' || stage.type === 'test') { failure = `${stage.title}: ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed'; }
          }
        } else if (stage.type === 'fix') this.ctx.known_issues = []; // resolved
        break;
      }
      hooks.stageEnd(stage, i, this.stages.length);
      this.log({ level: stage.status === 'failed' ? 'warn' : 'info', event: 'stage_completed', stage_id: stage.id, stage_type: stage.type, selected_model: stage.model, status: stage.status, execution_duration_ms: stage.ms, retry_count: stage.attempts - 1, escalation_level: stage.escalation });
      if (status !== 'completed') break;
    }
    for (const s of this.stages) if (s.status === 'pending') s.status = 'skipped';
    this.log({ level: status === 'completed' ? 'info' : 'warn', event: 'execution_finished', status, escalation_level: this.escalations });
    return { status, error: failure, stages: this.stages, switches: this.switches, escalations: this.escalations };
  }

  private withTimeout(p: Promise<TurnResult>, ms: number): Promise<TurnResult> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<TurnResult>((resolve) => {
      timer = setTimeout(() => {
        void this.deps.interrupt().catch(() => undefined);
        resolve({ status: 'failed', error: `stage timed out after ${Math.round(ms / 1000)}s` });
      }, ms);
      timer.unref?.();
    });
    return Promise.race([p, timeout]).finally(() => clearTimeout(timer));
  }
}

