test('adds', () => assert.equal((m.add ?? m.sum)(2, 3), 5));
",
};

export interface ScenarioResult {
  id: string; name: string; mode: 'mock' | 'real';
  route: { tier: string; model: string; effort: string; complexity: number; risk: string; referenceChars: number };
  strategy: string; plannedStages: number; stages: number; switches: number; escalations: number; models: string[];
  readOnly: boolean; sticky: boolean; compaction?: boolean;
  checks: { name: string; ok: boolean; expected: string; actual: string }[];
  /** Real mode only: provider-reported, per sample. */
  samples?: { usage?: TokenBreakdown; ms: number; status: string; verified?: boolean; stages: number; switches: number }[];
}

function check(s: Scenario, r: Omit<ScenarioResult, 'checks'>, cfg: RouterConfig): ScenarioResult['checks'] {
  const e = s.expect;
  const out: ScenarioResult['checks'] = [];
  const add = (name: string, ok: boolean, expected: string, actual: string) => out.push({ name, ok, expected, actual });
  const model = (m: string) => (Object.entries(cfg.models).find(([, v]) => v === m)?.[0] ?? (Object.entries(cfg.stages.tiers).find(([, v]) => v === m)?.[0] === 'fast' ? 'fast' : m));
  if (e.tiers) add('tier', e.tiers.includes(r.route.tier), e.tiers.join('|'), r.route.tier);
  if (e.models) add('model', e.models.some((t) => (cfg.models as Record<string, string>)[t] === r.route.model || cfg.stages.tiers[t as 'fast'] === r.route.model), e.models.join('|'), `${r.route.model} (${model(r.route.model)})`);
  if (e.efforts) add('reasoning', e.efforts.includes(r.route.effort), e.efforts.join('|'), r.route.effort);
  if (e.risk) add('risk', e.risk.includes(r.route.risk), e.risk.join('|'), r.route.risk);
  if (e.complexity) add('complexity', r.route.complexity >= e.complexity[0] && r.route.complexity <= e.complexity[1], `${e.complexity[0]}–${e.complexity[1]}`, String(r.route.complexity));
  if (e.strategy) add('strategy', e.strategy.includes(r.strategy), e.strategy.join('|'), r.strategy);
  if (e.plannedStages !== undefined) add('planned stages', r.plannedStages === e.plannedStages, String(e.plannedStages), String(r.plannedStages));
  if (e.stages) add('stages', r.stages >= e.stages[0] && r.stages <= e.stages[1], `${e.stages[0]}–${e.stages[1]}`, String(r.stages));
  if (e.switches) add('model switches', r.switches >= e.switches[0] && r.switches <= e.switches[1], `${e.switches[0]}–${e.switches[1]}`, String(r.switches));
  if (e.readOnly !== undefined) add('read-only', r.readOnly === e.readOnly, String(e.readOnly), String(r.readOnly));
  if (e.sticky !== undefined) add('kept previous selection', r.sticky === e.sticky, String(e.sticky), String(r.sticky));
  if (e.compaction !== undefined) add('compaction', r.compaction === e.compaction, String(e.compaction), String(r.compaction));
  if (e.referenceUsed) add('pasted reference not judged', r.route.referenceChars > 0, '>0 chars set aside', String(r.route.referenceChars));
  // global policy: the cheapest tier's model for trivial tiers
  if (r.route.tier === 'fast') add('simple task on the efficient model', r.route.model === cfg.models.fast, cfg.models.fast, r.route.model);
  return out;
}

function routeScenario(s: Scenario, cfg: RouterConfig, catalog: ModelInfo[]) {
  const router = new TurnRouter(cfg, '/nonexistent', catalog);
  const ticket = new TicketSession();
  let last;
  for (const msg of s.turns) {
    const tturn = s.ticket ? ticket.prepare(msg) : undefined;
    let pick = router.pick(tturn?.routeText ?? msg);
    const reading = Boolean(tturn?.readOnly);
    if (reading) pick = { ...pick, sel: readingSelection(pick.route, msg, ticket, catalog, cfg) };
    if (tturn) ticket.afterTurn('understood: order list badge', [], true);
    last = { pick, prompt: tturn?.prompt ?? msg, reading, text: msg };
  }
  return last!;
}

export async function runMock(cfg: RouterConfig, catalog: ModelInfo[], ids?: string[]): Promise<ScenarioResult[]> {
  const out: ScenarioResult[] = [];
  for (const s of SCENARIOS.filter((x) => !ids?.length || ids.includes(x.id))) {
    const { pick, prompt, reading } = routeScenario(s, cfg, catalog);
    const plan = reading ? undefined : planExecution(prompt, pick.route, cfg, pick.sel);
    let n = 0;
    const sent: Selection[] = [];
    let stages = 1; let switches = 0; let escalations = 0; let models = [pick.sel.model ?? '?'];
    if (plan && plan.strategy !== 'direct') {
      const exec = new StagedExecution(prompt, plan, {
        cfg: { ...cfg, analytics: { ...cfg.analytics, enabled: false } }, catalog,
        send: async (_p, sel) => { sent.push(sel); return { status: 'completed', items: [...(s.mock?.(n++) ?? []), { type: 'agentMessage', text: 'ok' }] } as TurnResult; },
        interrupt: async () => undefined, cancelled: () => false,
        hooks: { planned: () => undefined, stageStart: () => undefined, stageEnd: () => undefined, notice: () => undefined }, log: () => undefined,
      }, pick.sel);
      const r = await exec.run();
      stages = r.stages.filter((x) => x.status !== 'skipped').length; switches = r.switches; escalations = r.escalations; models = r.models;
    }
    let compaction: boolean | undefined;
    if (s.context) {
      const c = new Compactor(cfg.stages, async () => true);
      for (let i = 0; i < s.context.turns; i++) c.turnDone(s.context);
      compaction = c.decide(s.context).compact;
    }
    const base = {
      id: s.id, name: s.name, mode: 'mock' as const,
      route: { tier: pick.route.tier, model: pick.sel.model ?? pick.route.model, effort: pick.sel.effort ?? pick.route.reasoning_effort, complexity: pick.route.complexity_score, risk: pick.route.risk, referenceChars: pick.route.reference_chars },
      strategy: plan?.strategy ?? 'direct', plannedStages: plan?.stages.length ?? 1, stages, switches, escalations, models, readOnly: reading, sticky: pick.sticky, compaction,
    };
    out.push({ ...base, checks: check(s, base, cfg) });
  }
  return out;
}

const exec = new StagedExecution(prompt, plan, {
  cfg: { ...cfg, analytics: { ...cfg.analytics, enabled: false } }, catalog,
  send: async (_p, sel) => { sent.push(sel); return { status: 'completed', items: [...(s.mock?.(n++) ?? []), { type: 'agentMessage', text: 'ok' }] } as TurnResult; },
  interrupt: async () => undefined, cancelled: () => false,
  hooks: { planned: () => undefined, stageStart: () => undefined, stageEnd: () => undefined, notice: () => undefined }, log: () => undefined,
}, pick.sel);

const base = {
  id: s.id, name: s.name, mode: 'mock' as const,
  route: { tier: pick.route.tier, model: pick.sel.model ?? pick.route.model, effort: pick.sel.effort ?? pick.route.reasoning_effort, complexity: pick.route.complexity_score, risk: pick.route.risk, referenceChars: pick.route.reference_chars },
  strategy: plan?.strategy ?? 'direct', plannedStages: plan?.stages.length ?? 1, stages, switches, escalations, models, readOnly: reading, sticky: pick.sticky, compaction,
};

export interface RealDeps {
  /** Starts an isolated Codex session in `cwd` and returns a send function plus a closer. */
  session(cwd: string): Promise<{ send(prompt: string, sel: Selection, isolated: boolean): Promise<TurnResult>; context(): { used: number; window: number | null } | undefined; compact(): Promise<boolean>; close(): Promise<void> }>;
}

export async function runReal(cfg: RouterConfig, catalog: ModelInfo[], deps: RealDeps, opts: { confirmed: boolean; samples: number; ids?: string[]; onProgress?(msg: string): void }): Promise<ScenarioResult[]> {
  if (!opts.confirmed) throw new Error('real benchmarks run real Codex turns (subscription quota) and need explicit confirmation');
  if (!Number.isInteger(opts.samples) || opts.samples < 1 || opts.samples > 10) throw new Error('samples must be an integer from 1 to 10');
  const runnable = SCENARIOS.filter((s) => s.real && (!opts.ids?.length || opts.ids.includes(s.id)));
  if (!runnable.length) throw new Error(`no runnable scenario${opts.ids?.length ? ` among ${opts.ids.join(', ')}` : ''}; runnable: ${SCENARIOS.filter((s) => s.real).map((s) => s.id).join(', ')}`);
  const mock = await runMock(cfg, catalog, runnable.map((s) => s.id));
  const out: ScenarioResult[] = [];
  for (const s of runnable) {
    const m = mock.find((x) => x.id === s.id)!;
    const samples: NonNullable<ScenarioResult['samples']> = [];
    for (let k = 0; k < opts.samples; k++) {
      opts.onProgress?.(`${s.name} · sample ${k + 1}/${opts.samples}`);
      const dir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'lumina-bench-')));
      for (const [f, c] of Object.entries(s.real!.files)) { fs.mkdirSync(path.dirname(path.join(dir, f)), { recursive: true }); fs.writeFileSync(path.join(dir, f), c); }
      execFileSync('git', ['init', '-q'], { cwd: dir });
      execFileSync('git', ['add', '-A'], { cwd: dir });
      const sess = await deps.session(dir);
      const t0 = Date.now();
      try {
        const { pick, prompt } = routeScenario(s, cfg, catalog);
        const plan = planExecution(prompt, pick.route, cfg, pick.sel);
        const exec = new StagedExecution(prompt, plan, { cfg, catalog, send: (p, sel, o) => sess.send(p, sel, o.isolated), interrupt: async () => undefined, cancelled: () => false, context: () => sess.context(), compact: () => sess.compact(), hooks: { planned: () => undefined, stageStart: () => undefined, stageEnd: () => undefined, notice: () => undefined } }, pick.sel);
        const r = await exec.run();
        let verified: boolean | undefined;
        try { execFileSync(s.real!.verify[0], s.real!.verify.slice(1), { cwd: dir, stdio: 'ignore', timeout: 120_000 }); verified = true; } catch { verified = false; }
        samples.push({ usage: r.usageReported ? r.usage : undefined, ms: Date.now() - t0, status: r.status, verified, stages: r.stages.filter((x) => x.status !== 'skipped').length, switches: r.switches });
      } finally { await sess.close().catch(() => undefined); fs.rmSync(dir, { recursive: true, force: true }); }
    }
    out.push({ ...m, mode: 'real', samples, checks: m.checks });
  }
  return out;
}

export function aggregate(samples: NonNullable<ScenarioResult['samples']>) {
  const reported = samples.filter((x) => x.usage);
  return {
    samples: samples.length, reported: reported.length,
    input: median(reported.map((x) => x.usage!.inputTokens)), cached: median(reported.map((x) => x.usage!.cachedInputTokens)), output: median(reported.map((x) => x.usage!.outputTokens)),
    ms: median(samples.map((x) => x.ms)), stages: median(samples.map((x) => x.stages)), switches: median(samples.map((x) => x.switches)),
    verified: samples.filter((x) => x.verified).length,
  };
}

export function saveRun(run: StoredRun, file = resultsFile()): void {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  const keep = loadRuns(file).slice(-(MAX_RUNS - 1));
  fs.writeFileSync(`${file}.tmp`, `${[...keep, run].map((r) => JSON.stringify(r)).join('\n')}\n`, { mode: 0o600 });
  fs.renameSync(`${file}.tmp`, file);
}

export function loadRuns(file = resultsFile()): StoredRun[] {
  let text = '';
  try { text = fs.readFileSync(file, 'utf8'); } catch { return []; }
  const out: StoredRun[] = [];
  for (const l of text.split('\n')) { if (!l.trim()) continue; try { const r = JSON.parse(l) as StoredRun; if ((r.mode === 'mock' || r.mode === 'real') && Array.isArray(r.results)) out.push(r); } catch { /* skip */ } }
  return out;
}

export function regressions(prev: StoredRun | undefined, cur: StoredRun): string[] {
  if (!prev) return [];
  const out: string[] = [];
  for (const c of cur.results) {
    const p = prev.results.find((x) => x.id === c.id);
    if (!p) continue;
    if (cur.mode === 'mock') {
      for (const [k, a, b] of [['model', p.route.model, c.route.model], ['reasoning', p.route.effort, c.route.effort], ['tier', p.route.tier, c.route.tier], ['risk', p.route.risk, c.route.risk], ['stages', String(p.stages), String(c.stages)], ['planned stages', String(p.plannedStages), String(c.plannedStages)]] as const) {
        if (a !== b) out.push(`${c.id}: ${k} changed ${a} → ${b}`);
      }
      continue;
    }
    if (!p.samples || !c.samples || p.samples.length < 3 || c.samples.length < 3) continue;
    const pa = aggregate(p.samples); const ca = aggregate(c.samples);
    if (pa.input && ca.input && ca.input > pa.input * 1.25) out.push(`${c.id}: median input tokens ${pa.input.toLocaleString('en-US')} → ${ca.input.toLocaleString('en-US')} (provider-reported)`);
    if (pa.output && ca.output && ca.output > pa.output * 1.25) out.push(`${c.id}: median output tokens ${pa.output.toLocaleString('en-US')} → ${ca.output.toLocaleString('en-US')} (provider-reported)`);
    if (ca.verified / c.samples.length < pa.verified / p.samples.length - 0.2) out.push(`${c.id}: verified results ${pa.verified}/${p.samples.length} → ${ca.verified}/${c.samples.length}`);
  }
  return out;
}

export function formatRun(cur: StoredRun, prev: StoredRun | undefined): string {
  const out = [`Routing Benchmark · ${cur.mode === 'mock' ? 'MOCK (no model calls; deterministic expectations)' : 'REAL (Codex executions; observed, provider-reported)'} · ${cur.results.length} scenario${cur.results.length === 1 ? '' : 's'}`, ''];
  for (const r of cur.results) {
    const bad = r.checks.filter((c) => !c.ok);
    out.push(`${bad.length ? '✗' : '✓'} ${r.name} [${r.id}]: ${r.route.model}/${r.route.effort} · ${r.route.tier} · risk ${r.route.risk} · complexity ${r.route.complexity} · ${r.strategy} · stages ${r.stages}${r.switches ? ` · switches ${r.switches}` : ''}${r.readOnly ? ' · read-only' : ''}${r.sticky ? ' · kept previous selection' : ''}${r.compaction !== undefined ? ` · compaction ${r.compaction ? 'yes' : 'no'}` : ''}`);
    for (const c of bad) out.push(`    expected ${c.name} ${c.expected}, got ${c.actual}`);
    if (r.samples) {
      const a = aggregate(r.samples);
      out.push(`    ${a.samples} sample${a.samples === 1 ? '' : 's'} · verified ${a.verified}/${a.samples} · median ${a.ms !== undefined ? `${Math.round(a.ms / 1000)}s` : '—'} · stages ${a.stages} · switches ${a.switches} · ${a.reported ? `median tokens in ${a.input?.toLocaleString('en-US')} / cached ${a.cached?.toLocaleString('en-US')} / out ${a.output?.toLocaleString('en-US')} (${a.reported}/${a.samples} reported)` : 'tokens not reported'}`);
    }
  }
  const failed = cur.results.flatMap((r) => r.checks.filter((c) => !c.ok));
  const reg = regressions(prev, cur);
  out.push('', `Expectations: ${cur.results.reduce((n, r) => n + r.checks.length, 0) - failed.length}/${cur.results.reduce((n, r) => n + r.checks.length, 0)} passed`);
  out.push(prev ? (reg.length ? `Changes since the previous ${cur.mode} run (${new Date(prev.at).toISOString().slice(0, 16).replace('T', ' ')}):\n${reg.map((x) => `  - ${x}`).join('\n')}` : `No changes since the previous ${cur.mode} run.`) : `No previous ${cur.mode} run to compare with.`);
  if (cur.mode === 'mock') out.push('Mock results are expectations of the routing logic, not measured performance. Real runs: /benchmark real [samples] [scenario ids] (uses Codex quota; asks first).');
  else out.push('Real results are observations from these runs; differences under 3 samples per side are not treated as regressions. No savings are claimed without such measurements.');
  return out.join('\n');
}

export interface BudgetLimits {
  stages: number; escalations: number; switches: number; retries: number; stageTimeoutMs: number;
  repairs: number; repairEscalations: number;
  /** 0 = no limit. */ durationMs: number; inputTokens: number; outputTokens: number;
}

export function limitsFrom(cfg: RouterConfig): BudgetLimits {
  return {
    stages: cfg.stages.max_stages, escalations: cfg.stages.max_escalations, switches: cfg.stages.max_switches, retries: cfg.stages.max_retries, stageTimeoutMs: cfg.stages.stage_timeout_ms,
    repairs: cfg.self_healing.max_repair_attempts, repairEscalations: cfg.self_healing.max_escalations,
    durationMs: cfg.budget.max_duration_ms, inputTokens: cfg.budget.max_input_tokens, outputTokens: cfg.budget.max_output_tokens,
  };
}

export class Budget {
  readonly started: number;
  stages = 0; repairs = 0; escalations = 0; switches = 0;
  usage = { inputTokens: 0, cachedInputTokens: 0, outputTokens: 0 };
  /** Turns whose usage Codex reported, and turns it did not. */
  reported = 0; unreported = 0;
  stopped?: { reason: string; unfinished: string[] };
  private stageMs: number[] = [];

  constructor(readonly limits: BudgetLimits, readonly critical = false, private readonly now: () => number = Date.now) { this.started = now(); }

  private turnStart?: number;
  /** A Codex turn (stage or repair) is about to start. */
  beginTurn(): void { this.turnStart = this.now(); }
  /** It finished: its provider-reported usage, when there is one, and its duration. */
  turn(usage: TokenBreakdown | undefined): void {
    if (usage) { this.reported++; this.usage.inputTokens += usage.inputTokens; this.usage.cachedInputTokens += usage.cachedInputTokens; this.usage.outputTokens += usage.outputTokens; } else this.unreported++;
    if (this.turnStart !== undefined) { this.stageMs.push(this.now() - this.turnStart); this.turnStart = undefined; }
  }

  get elapsed(): number { return this.now() - this.started; }

  /** Fraction of the most-used optional dimension (time or tokens); 0 when none is limited or measured. */
  private used(): number {
    const l = this.limits;
    const f: number[] = [];
    if (l.durationMs) f.push(this.elapsed / l.durationMs);
    if (l.inputTokens && this.reported) f.push(this.usage.inputTokens / l.inputTokens);
    if (l.outputTokens && this.reported) f.push(this.usage.outputTokens / l.outputTokens);
    return f.length ? Math.max(...f) : 0;
  }

  /**
   * Before an additional stage or repair: the hard limits (time, tokens), then whether the expected benefit justifies
   * spending most of what is left. Critical (security-sensitive) work is never denied for "low benefit" reasons.
   */
  allow(kind: 'stage' | 'repair', benefit: Benefit): { ok: true } | { ok: false; reason: string } {
    const l = this.limits;
    const avg = this.stageMs.length ? this.stageMs.reduce((a, b) => a + b, 0) / this.stageMs.length : 0;
    if (l.durationMs && this.elapsed + avg > l.durationMs) return { ok: false, reason: `time budget: ${Math.round(this.elapsed / 1000)}s used of ${Math.round(l.durationMs / 1000)}s${avg ? `, and another ${kind} takes about ${Math.round(avg / 1000)}s` : ''}` };
    if (l.inputTokens && this.reported && this.usage.inputTokens >= l.inputTokens) return { ok: false, reason: `input token threshold: ${this.usage.inputTokens.toLocaleString('en-US')} of ${l.inputTokens.toLocaleString('en-US')} (provider-reported)` };
    if (l.outputTokens && this.reported && this.usage.outputTokens >= l.outputTokens) return { ok: false, reason: `output token threshold: ${this.usage.outputTokens.toLocaleString('en-US')} of ${l.outputTokens.toLocaleString('en-US')} (provider-reported)` };
    if (benefit === 'low' && !this.critical && this.used() >= 0.75) return { ok: false, reason: `low expected benefit with ${Math.round(this.used() * 100)}% of the budget used` };
    return { ok: true };
  }

  stop(reason: string, unfinished: string[]): void { this.stopped = { reason, unfinished }; }

  /** /budget lines: limits, consumption (provider-reported tokens only), and why tokens may be unknown. */
  format(title = 'Last request'): string[] {
    const l = this.limits;
    const t = (n: number) => n.toLocaleString('en-US');
    const out = [`${title}:`, `  Stages: ${this.stages} of ${l.stages}${l.escalations ? ` (+ up to ${l.escalations} escalation stages)` : ''} · Escalations: ${this.escalations} of ${l.escalations} · Model switches: ${this.switches} of ${l.switches}`, `  Repair attempts: ${this.repairs} of ${l.repairs}`, `  Duration: ${Math.round(this.elapsed / 1000)}s${l.durationMs ? ` of ${Math.round(l.durationMs / 1000)}s` : ' (no time limit)'}`];
    if (this.reported) out.push(`  Tokens (provider-reported${this.unreported ? `; ${this.unreported} turn${this.unreported === 1 ? '' : 's'} not reported` : ''}): input ${t(this.usage.inputTokens)}${l.inputTokens ? ` of ${t(l.inputTokens)}` : ''} (cached ${t(this.usage.cachedInputTokens)}) · output ${t(this.usage.outputTokens)}${l.outputTokens ? ` of ${t(l.outputTokens)}` : ''}`);
    else out.push(`  Tokens: not reported by Codex${l.inputTokens || l.outputTokens ? ' — token thresholds cannot be enforced for this request' : ''}`);
    if (this.stopped) out.push(`  Stopped: ${this.stopped.reason}`, ...this.stopped.unfinished.map((u) => `    unfinished: ${u}`), '  /continue resumes it with a fresh budget.');
    return out;
  }
}

turn(usage: TokenBreakdown | undefined): void {
  if (usage) { this.reported++; this.usage.inputTokens += usage.inputTokens; this.usage.cachedInputTokens += usage.cachedInputTokens; this.usage.outputTokens += usage.outputTokens; } else this.unreported++;
  if (this.turnStart !== undefined) { this.stageMs.push(this.now() - this.turnStart); this.turnStart = undefined; }
}

private used(): number {
  const l = this.limits;
  const f: number[] = [];
  if (l.durationMs) f.push(this.elapsed / l.durationMs);
  if (l.inputTokens && this.reported) f.push(this.usage.inputTokens / l.inputTokens);
  if (l.outputTokens && this.reported) f.push(this.usage.outputTokens / l.outputTokens);
  return f.length ? Math.max(...f) : 0;
}

allow(kind: 'stage' | 'repair', benefit: Benefit): { ok: true } | { ok: false; reason: string } {
  const l = this.limits;
  const avg = this.stageMs.length ? this.stageMs.reduce((a, b) => a + b, 0) / this.stageMs.length : 0;
  if (l.durationMs && this.elapsed + avg > l.durationMs) return { ok: false, reason: `time budget: ${Math.round(this.elapsed / 1000)}s used of ${Math.round(l.durationMs / 1000)}s${avg ? `, and another ${kind} takes about ${Math.round(avg / 1000)}s` : ''}` };
  if (l.inputTokens && this.reported && this.usage.inputTokens >= l.inputTokens) return { ok: false, reason: `input token threshold: ${this.usage.inputTokens.toLocaleString('en-US')} of ${l.inputTokens.toLocaleString('en-US')} (provider-reported)` };
  if (l.outputTokens && this.reported && this.usage.outputTokens >= l.outputTokens) return { ok: false, reason: `output token threshold: ${this.usage.outputTokens.toLocaleString('en-US')} of ${l.outputTokens.toLocaleString('en-US')} (provider-reported)` };
  if (benefit === 'low' && !this.critical && this.used() >= 0.75) return { ok: false, reason: `low expected benefit with ${Math.round(this.used() * 100)}% of the budget used` };
  return { ok: true };
}

format(title = 'Last request'): string[] {
  const l = this.limits;
  const t = (n: number) => n.toLocaleString('en-US');
  const out = [`${title}:`, `  Stages: ${this.stages} of ${l.stages}${l.escalations ? ` (+ up to ${l.escalations} escalation stages)` : ''} · Escalations: ${this.escalations} of ${l.escalations} · Model switches: ${this.switches} of ${l.switches}`, `  Repair attempts: ${this.repairs} of ${l.repairs}`, `  Duration: ${Math.round(this.elapsed / 1000)}s${l.durationMs ? ` of ${Math.round(l.durationMs / 1000)}s` : ' (no time limit)'}`];
  if (this.reported) out.push(`  Tokens (provider-reported${this.unreported ? `; ${this.unreported} turn${this.unreported === 1 ? '' : 's'} not reported` : ''}): input ${t(this.usage.inputTokens)}${l.inputTokens ? ` of ${t(l.inputTokens)}` : ''} (cached ${t(this.usage.cachedInputTokens)}) · output ${t(this.usage.outputTokens)}${l.outputTokens ? ` of ${t(l.outputTokens)}` : ''}`);
  else out.push(`  Tokens: not reported by Codex${l.inputTokens || l.outputTokens ? ' — token thresholds cannot be enforced for this request' : ''}`);
  if (this.stopped) out.push(`  Stopped: ${this.stopped.reason}`, ...this.stopped.unfinished.map((u) => `    unfinished: ${u}`), '  /continue resumes it with a fresh budget.');
  return out;
}

export function formatLimits(l: BudgetLimits): string[] {
  const t = (n: number) => n.toLocaleString('en-US');
  return [
    'Budget limits (per request):',
    `  Stages: ${l.stages} planned, + up to ${l.escalations} escalation stage${l.escalations === 1 ? '' : 's'} · retries per stage: ${l.retries} · model switches: ${l.switches} · stage timeout: ${Math.round(l.stageTimeoutMs / 1000)}s`,
    `  Self-healing: ${l.repairs} repair attempt${l.repairs === 1 ? '' : 's'} · ${l.repairEscalations} escalation${l.repairEscalations === 1 ? '' : 's'}`,
    `  Duration: ${l.durationMs ? `${Math.round(l.durationMs / 1000)}s` : 'no limit'} · Input tokens: ${l.inputTokens ? t(l.inputTokens) : 'no threshold'} · Output tokens: ${l.outputTokens ? t(l.outputTokens) : 'no threshold'}`,
    '  Verification and safety checks are never skipped to stay within budget. Tokens are provider-reported counts, not billing.',
  ];
}

export interface Manifest {
  version: 1; id: string; root: string; createdAt: number; task: string; status: CheckpointStatus;
  head: string | null; pre: Record<string, PreEntry>; changes: FileChange[]; finishedAt?: number; rolledBackAt?: number;
}

function git(cwd: string, args: string[], encoding: 'utf8' | 'buffer' = 'utf8'): Promise<string | Buffer> {
  return new Promise((resolve, reject) => {
    execFile('git', ['-c', 'core.quotepath=off', '--no-pager', ...args], { cwd, encoding, maxBuffer: 256 * 1024 * 1024 }, (err, stdout, stderr) => {
      if (err) return reject(new Error(String(stderr || err.message).split('\n')[0].replace(/^fatal:\s*/, '')));
      resolve(stdout);
    });
  });
}

return new Promise((resolve, reject) => {
  execFile('git', ['-c', 'core.quotepath=off', '--no-pager', ...args], { cwd, encoding, maxBuffer: 256 * 1024 * 1024 }, (err, stdout, stderr) => {
    if (err) return reject(new Error(String(stderr || err.message).split('\n')[0].replace(/^fatal:\s*/, '')));
    resolve(stdout);
  });
});

execFile('git', ['-c', 'core.quotepath=off', '--no-pager', ...args], { cwd, encoding, maxBuffer: 256 * 1024 * 1024 }, (err, stdout, stderr) => {
  if (err) return reject(new Error(String(stderr || err.message).split('\n')[0].replace(/^fatal:\s*/, '')));
  resolve(stdout);
});

export function safeRelative(root: string, rel: string): string {
  if (!rel || rel.includes('\0') || path.isAbsolute(rel) || rel.split(/[\\/]/).some((seg) => seg === '..')) throw new Error(`unsafe path in checkpoint: ${JSON.stringify(rel)}`);
  const abs = path.resolve(root, rel);
  if (!abs.startsWith(root + path.sep)) throw new Error(`path outside the repository: ${rel}`);
  // no symlinked ancestor may lead outside the repository
  let dir = path.dirname(abs);
  while (dir.startsWith(root) && dir !== root) {
    if (fs.existsSync(dir)) { if (!fs.realpathSync(dir).startsWith(root)) throw new Error(`path escapes the repository via a symlink: ${rel}`); break; }
    dir = path.dirname(dir);
  }
  return abs;
}

function currentSha(abs: string): Sha | 'symlink' {
  try {
    const st = fs.lstatSync(abs);
    if (st.isSymbolicLink()) return 'symlink';
    if (!st.isFile()) return null;
    return blobSha(fs.readFileSync(abs));
  } catch { return null; }
}

async function dirtyPaths(root: string): Promise<string[]> {
  const out = await gitText(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all']);
  const f = out.split('\0');
  const paths: string[] = [];
  for (let i = 0; i < f.length; i++) {
    if (f[i].length < 4) continue;
    paths.push(f[i].slice(3));
    if (f[i][0] === 'R' || f[i][0] === 'C') paths.push(f[++i]); // the old name of a rename/copy is affected too
  }
  return paths;
}

async function headBlobs(root: string, head: string | null, paths: string[]): Promise<Map<string, string>> {
  const map = new Map<string, string>();
  if (!head) return map;
  for (let i = 0; i < paths.length; i += 200) {
    const out = await gitText(root, ['ls-tree', '-z', head, '--', ...paths.slice(i, i + 200)]);
    for (const e of out.split('\0')) { const m = /^(\d+) (\w+) ([0-9a-f]+)\t(.*)$/s.exec(e); if (m && m[2] === 'blob') map.set(m[4], m[3]); }
  }
  return map;
}

export class CheckpointStore {
  readonly root: string;
  readonly dir: string;
  private constructor(root: string, private readonly cfg: RouterConfig['checkpoints']) {
    this.root = root;
    this.dir = path.join(stateDir(), 'checkpoints', createHash('sha1').update(root).digest('hex').slice(0, 16));
  }

  /** Store for the git repository containing `cwd`, or an error explaining why checkpoints are unavailable. */
  static async open(cwd: string, cfg: RouterConfig['checkpoints']): Promise<CheckpointStore> {
    const top = (await gitText(cwd, ['rev-parse', '--show-toplevel'])).trim();
    return new CheckpointStore(fs.realpathSync(top), cfg);
  }

  private cpDir(id: string): string {
    if (!/^[a-z0-9]{8,32}$/.test(id)) throw new Error(`invalid checkpoint id: ${id}`);
    return path.join(this.dir, id);
  }
  private save(m: Manifest): void {
    fs.mkdirSync(this.cpDir(m.id), { recursive: true });
    const file = path.join(this.cpDir(m.id), 'manifest.json');
    fs.writeFileSync(`${file}.tmp`, JSON.stringify(m));
    fs.renameSync(`${file}.tmp`, file); // atomic
  }
  private storeBlob(id: string, sha: string, buf: Buffer): void {
    const f = path.join(this.cpDir(id), 'blobs', sha);
    if (fs.existsSync(f)) return;
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, buf);
  }
  private readBlob(id: string, sha: string): Buffer {
    if (!/^[0-9a-f]{40}$/.test(sha)) throw new Error('invalid blob id');
    const buf = fs.readFileSync(path.join(this.cpDir(id), 'blobs', sha));
    if (blobSha(buf) !== sha) throw new Error(`checkpoint data for ${sha.slice(0, 8)} is corrupted`);
    return buf;
  }

  load(id: string): Manifest {
    const m = JSON.parse(fs.readFileSync(path.join(this.cpDir(id), 'manifest.json'), 'utf8')) as Manifest;
    if (m.version !== 1 || m.id !== id || m.root !== this.root) throw new Error(`checkpoint ${id} does not belong to this repository`);
    for (const c of m.changes) safeRelative(this.root, c.path); // never trust stored paths
    return m;
  }

  /** All checkpoints of this repository, newest first. A pending one from a crashed session is reported as incomplete. */
  list(): Manifest[] {
    if (!fs.existsSync(this.dir)) return [];
    const out: Manifest[] = [];
    for (const id of fs.readdirSync(this.dir)) {
      try {
        const m = this.load(id);
        if (m.status === 'pending' && Date.now() - m.createdAt > 6 * 3600 * 1000) m.status = 'incomplete';
        out.push(m);
      } catch { /* unreadable entry: ignored */ }
    }
    return out.sort((a, b) => b.createdAt - a.createdAt);
  }

  /** Before a code-modifying turn: record the dirty part of the working tree. */
  async begin(task: string): Promise<Manifest> {
    this.cleanup();
    const id = randomUUID().replace(/-/g, '').slice(0, 12);
    const head = (await gitText(this.root, ['rev-parse', '--verify', '-q', 'HEAD']).catch(() => '')).trim() || null;
    const m: Manifest = { version: 1, id, root: this.root, createdAt: Date.now(), task: task.replace(/\s+/g, ' ').trim().slice(0, 160), status: 'pending', head, pre: {}, changes: [] };
    let total = 0;
    for (const rel of await dirtyPaths(this.root)) {
      const abs = safeRelative(this.root, rel);
      let st: fs.Stats | undefined;
      try { st = fs.lstatSync(abs); } catch { st = undefined; }
      if (!st) { m.pre[rel] = { sha: null, stored: true }; continue; }
      if (st.isSymbolicLink()) { m.pre[rel] = { sha: null, stored: false, unsafe: 'symlink' }; continue; }
      if (!st.isFile()) continue;
      if (st.size > this.cfg.max_file_bytes || total + st.size > this.cfg.max_total_bytes) { m.pre[rel] = { sha: null, stored: false, unsafe: 'oversize', fp: `${st.size}:${st.mtimeMs}` }; continue; }
      const buf = fs.readFileSync(abs);
      const sha = blobSha(buf);
      this.storeBlob(id, sha, buf);
      total += buf.length;
      m.pre[rel] = { sha, stored: true };
    }
    this.save(m);
    return m;
  }

  /** After the turn: record what changed (and keep the "before" bytes). */
  async finish(m: Manifest, interrupted: boolean): Promise<Manifest> {
    const headNow = (await gitText(this.root, ['rev-parse', '--verify', '-q', 'HEAD']).catch(() => '')).trim() || null;
    const candidates = new Set([...Object.keys(m.pre), ...await dirtyPaths(this.root)]);
    if (m.head && headNow && headNow !== m.head) { // the turn committed: files in those commits changed too
      for (const p of (await gitText(this.root, ['diff', '--name-only', '-z', m.head, headNow])).split('\0')) if (p) candidates.add(p);
    }
    const inHead = await headBlobs(this.root, m.head, [...candidates].filter((p) => !(p in m.pre)));
    const changes: FileChange[] = [];
    for (const rel of candidates) {
      const abs = safeRelative(this.root, rel);
      const pre = m.pre[rel];
      if (pre?.unsafe === 'oversize') { // not snapshotted: untouched → ignore; touched → cannot be restored
        let fp = '';
        try { const st = fs.lstatSync(abs); fp = `${st.size}:${st.mtimeMs}`; } catch { /* gone */ }
        if (fp === pre.fp) continue;
        changes.push({ path: rel, before: null, after: null, unsafe: 'too large to snapshot before the change' });
        continue;
      }
      const before: Sha = pre ? pre.sha : inHead.get(rel) ?? null;
      const now = currentSha(abs);
      if (pre?.unsafe === 'symlink' && now === 'symlink') continue; // untouched pre-existing symlink
      if (now !== 'symlink' && pre?.unsafe !== 'symlink' && before === now) continue;
      const change: FileChange = { path: rel, before, after: now === 'symlink' ? null : now };
      if (now === 'symlink') change.unsafe = 'is a symlink now';
      else if (pre?.unsafe === 'symlink') change.unsafe = 'was a symlink';
      if (!pre && before && !change.unsafe) { // clean before the turn: keep the HEAD bytes so rollback never depends on git history
        try { this.storeBlob(m.id, before, await git(this.root, ['cat-file', 'blob', before], 'buffer') as Buffer); } catch { change.unsafe = 'original content unavailable'; }
      }
      changes.push(change);
    }
    m.changes = changes.sort((a, b) => a.path.localeCompare(b.path));
    m.status = !changes.length ? 'no-changes' : interrupted ? 'interrupted' : 'active';
    m.finishedAt = Date.now();
    if (m.status === 'no-changes') this.remove(m.id); else this.save(m);
    return m;
  }

  /** What a rollback would do; `blocked` explains why it cannot run automatically. */
  plan(id: string): RollbackPlan {
    const m = this.load(id);
    if (m.status === 'rolled-back') return { checkpoint: m, items: [], blocked: 'this checkpoint was already rolled back' };
    if (m.status === 'pending' || m.status === 'incomplete') return { checkpoint: m, items: [], blocked: 'the execution never finished recording its changes (Lumina was stopped), so Lumina cannot tell its edits from yours' };
    const items: PlanItem[] = m.changes.map((c) => {
      const abs = safeRelative(this.root, c.path);
      const action: PlanItem['action'] = c.before === null ? 'delete' : c.after === null ? 'recreate' : 'restore';
      if (c.unsafe) return { path: c.path, action, conflict: c.unsafe };
      const now = currentSha(abs);
      if (now === 'symlink') return { path: c.path, action, conflict: 'is a symlink now' };
      if (now !== c.after) return { path: c.path, action, conflict: now === null ? 'deleted after the checkpoint' : 'changed after Lumina edited it (newer manual edit or another process)' };
      return { path: c.path, action };
    });
    const conflicts = items.filter((i) => i.conflict).length;
    return { checkpoint: m, items, blocked: conflicts ? `${conflicts} file${conflicts === 1 ? '' : 's'} changed since — rolling back would overwrite work that is not Lumina's` : undefined };
  }

  /**
   * Applies a conflict-free plan all-or-nothing: current bytes are backed up first; if any write fails, every file
   * already touched is put back. Only working-tree files are changed (no git index, no commits, no remotes).
   */
  rollback(id: string, hooks: { beforeWrite?: (rel: string) => void } = {}): { restored: number } {
    const plan = this.plan(id);
    if (plan.blocked) throw new Error(plan.blocked);
    const m = plan.checkpoint;
    const backup = path.join(this.cpDir(id), `rollback-${Date.now()}`);
    fs.mkdirSync(backup, { recursive: true });
    const done: { rel: string; abs: string; had: boolean; bak: string }[] = [];
    try {
      for (const c of m.changes) {
        const abs = safeRelative(this.root, c.path);
        const bak = path.join(backup, createHash('sha1').update(c.path).digest('hex'));
        const had = fs.existsSync(abs);
        if (had) fs.copyFileSync(abs, bak);
        done.push({ rel: c.path, abs, had, bak });
        hooks.beforeWrite?.(c.path);
        if (c.before === null) { if (had) fs.unlinkSync(abs); continue; }
        const buf = this.readBlob(id, c.before);
        fs.mkdirSync(path.dirname(abs), { recursive: true });
        const tmp = path.join(path.dirname(abs), `.lumina-rollback-${randomUUID().slice(0, 8)}`);
        fs.writeFileSync(tmp, buf);
        fs.renameSync(tmp, abs); // atomic per file
      }
    } catch (e) {
      const failedAt = done.at(-1)?.rel ?? '?';
      // undo everything already applied, newest first
      for (const d of [...done].reverse()) {
        try { if (d.had) fs.copyFileSync(d.bak, d.abs); else if (fs.existsSync(d.abs)) fs.unlinkSync(d.abs); } catch { /* reported below */ }
      }
      throw new Error(`rollback failed at ${failedAt} (${e instanceof Error ? e.message : String(e)}); all files were put back as they were`);
    }
    m.status = 'rolled-back';
    m.rolledBackAt = Date.now();
    this.save(m);
    return { restored: m.changes.length };
  }

  private remove(id: string): void { fs.rmSync(this.cpDir(id), { recursive: true, force: true }); }

  /** Retention: keep at most max_count checkpoints and none older than max_age_days (only Lumina's own storage). */
  cleanup(): void {
    const all = this.list();
    const cutoff = Date.now() - this.cfg.max_age_days * 86400000;
    all.forEach((m, i) => { if (i >= this.cfg.max_count || m.createdAt < cutoff) this.remove(m.id); });
  }
}

