export function trackRequest<T extends (...args: never[]) => unknown>(handler: T): T {
  return (async (...args: Parameters<T>) => {
    activeRequests += 1;
    try {
      return await handler(...args);
    } finally {
      activeRequests -= 1;
    }
  }) as T;
}

