export interface SkillDecision {
  request: string;
  mode: 'explicit' | 'auto' | 'none';
  selected: Picked[];
  explicit: SkillInfo[];
  /** Candidates that matched but were not used, and why (conflict, unavailable, limit). */
  dropped: { skill: SkillInfo; reason: string }[];
  note?: string;
  /** The prompt carried pasted reference material, which was ignored for selection. */
  pasted?: boolean;
}

const ID: Record<string, string> = {
  tinjau: 'review', tinjauan: 'review', periksa: 'review', cek: 'review', telaah: 'review', ulas: 'review', audit: 'audit',
  keamanan: 'security', aman: 'security', autentikasi: 'authentication', otentikasi: 'authentication', otorisasi: 'authorization', login: 'login',
  uji: 'test', pengujian: 'test', tes: 'test', dokumentasi: 'documentation', dokumen: 'documentation', perbaiki: 'fix', benahi: 'fix',
  komit: 'commit', rilis: 'release', terjemah: 'translate', terjemahkan: 'translate', desain: 'design', tampilan: 'ui', gambar: 'image',
  basi: 'database', // "basis (data)" after plural stemming
  kinerja: 'performance', performa: 'performance', rapikan: 'refactor', refaktor: 'refactor', migrasi: 'migration', basis: 'database', ringkas: 'summary', ringkasan: 'summary',
  jelaskan: 'explain', selidiki: 'investigate', investigasi: 'investigate', rencana: 'plan', rencanakan: 'plan',
};

export function unavailable(s: SkillInfo): string | undefined {
  const missing = (s.tools ?? []).filter((t) => t.type === 'env_var' && !process.env[t.value]).map((t) => t.value);
  return missing.length ? `needs ${missing.join(', ')} (not set)` : undefined;
}

export function selectSkills(text: string, skills: SkillInfo[], opts: { auto: boolean; maxAuto: number }): SkillDecision {
  const explicit = mentionedSkills(text, skills);
  const base = { request: text, selected: [], dropped: [] as SkillDecision['dropped'] };
  // explicit $skill wins; auto-selection never adds to it
  if (explicit.length) return { ...base, mode: 'explicit', explicit };
  if (!opts.auto || opts.maxAuto === 0) return { ...base, mode: 'none', explicit: [], note: 'automatic skill selection is off (skills.auto_select)' };
  // judge the request, not pasted docs/tickets that merely mention skill names
  const sp = splitPrompt(text);
  // a long prompt without a short request paragraph is all pasted material: nothing in it is the user's intent
  const pasted = Boolean(sp.reference) || text.length > 600;
  if (!sp.reference && text.length > 600) return { ...base, mode: 'none', explicit: [], pasted, note: 'no short request found in the pasted text; use $skill to pick one' };
  const said = termMap(pasted ? sp.instruction : text); // stem → the word as the user wrote it (for /why)
  const req = new Set(said.keys());
  const cands: Picked[] = [];
  for (const s of skills) {
    const nameTerms = terms(s.name);
    const nameHits = [...nameTerms].filter((w) => req.has(w));
    // a skill is chosen for what it IS: its whole name (or two of its name words) must be in the request,
    // or part of its name plus a description that clearly fits (two or more of its words)
    const full = nameHits.length > 0 && nameHits.length === nameTerms.size;
    const descHits = [...terms(s.description)].filter((w) => req.has(w) && !nameTerms.has(w));
    if (!full && nameHits.length < 2 && !(nameHits.length && descHits.length >= 2)) continue;
    const score = 2 * nameHits.length + (full ? 1 : 0) + Math.min(descHits.length, 3);
    // one-word names ("migration") also need their description to fit the request
    if (score >= 4) cands.push({ skill: s, score, nameHits: nameHits.map((w) => said.get(w) ?? w), descHits: descHits.map((w) => said.get(w) ?? w) });
  }
  cands.sort((a, b) => b.score - a.score || (PRIORITY[a.skill.scope] ?? 9) - (PRIORITY[b.skill.scope] ?? 9) || a.skill.name.localeCompare(b.skill.name));
  const selected: Picked[] = [];
  const dropped = base.dropped;
  for (const c of cands) {
    const why = unavailable(c.skill);
    if (why) { dropped.push({ skill: c.skill, reason: why }); continue; }
    // skills of the same family (sharing a name word, e.g. review / security-review) give competing instructions: keep the best
    const rival = selected.find((p) => [...terms(p.skill.name)].some((w) => terms(c.skill.name).has(w)));
    if (rival) { dropped.push({ skill: c.skill, reason: `conflicts with ${rival.skill.name} (same kind of skill; the better match was kept)` }); continue; }
    if (selected.length >= opts.maxAuto) { dropped.push({ skill: c.skill, reason: `limit of ${opts.maxAuto} automatic skill(s)` }); continue; }
    selected.push(c);
  }
  return { ...base, dropped, mode: selected.length ? 'auto' : 'none', explicit: [], selected, pasted };
}

export function explainDecision(d: SkillDecision | undefined): string {
  if (!d) return 'No request has been sent yet in this session.';
  const req = d.request.split('\n')[0].slice(0, 120);
  if (d.mode === 'explicit') return `Skills: ${d.explicit.map((s) => `$${s.name} [${scopeLabel(s.scope)}]`).join(', ')}\nWhy: you invoked ${d.explicit.length === 1 ? 'it' : 'them'} explicitly with $name (automatic selection is skipped then).\nRequest: "${req}"`;
  const lines: string[] = [];
  if (d.mode === 'none') lines.push(`No skill was selected for the last request${d.note ? ` (${d.note})` : ' — no available skill matched what was asked'}. Codex may still use one on its own.`);
  for (const p of d.selected) {
    lines.push(`Skill: ${p.skill.name} [${scopeLabel(p.skill.scope)}]`);
    lines.push(`Why: its name matches ${p.nameHits.map((w) => `"${w}"`).join(', ')}${p.descHits.length ? `; its description also covers ${p.descHits.map((w) => `"${w}"`).join(', ')}` : ''}`);
    if (p.skill.description) lines.push(`About: ${p.skill.description.slice(0, 160)}`);
  }
  for (const x of d.dropped) lines.push(`Not used: ${x.skill.name} — ${x.reason}`);
  lines.push(`Request: "${req}"${d.pasted ? ' (pasted reference material is not used for skill selection)' : ''}`);
  return lines.join('\n');
}

export interface Stage {
  id: string; type: StageType; title: string; tier: Tier; effort: string; status: StageStatus;
  model?: string; attempts: number; escalation: number; outcome?: string; ms?: number; reason: string;
  thread?: 'shared' | 'isolated'; usage?: TokenBreakdown;
}

const CUE = {
  design: /\b(architect\w*|design|schema|data model|rbac|permissions?|authori[sz]ation|multi-?tenant|migrations?)\b/i,
  tests: /\b(tests?|testing|unit tests?|e2e|coverage|pengujian)\b/i,
  review: /\b(review|audit|security check|keamanan)\b/i,
  docs: /\b(docs?|documentation|readme|dokumentasi)\b/i,
  migration: /\b(migrations?|schema|database)\b/i,
};

export interface ExecutionPlan {
  strategy: Strategy;
  stages: Stage[];
  /** add a review stage after execution if (and only if) the request modified files */
  reviewAfter: boolean;
  /** escalation and lazily added stages allowed */
  adaptive: boolean;
}

export function raiseEffort(effort: string, cap: 'high' | 'xhigh' = 'high'): string {
  const i = Math.max(EFFORTS.indexOf(effort), 0);
  return EFFORTS[Math.min(Math.max(i + 1, 1), EFFORTS.indexOf(cap))];
}

export function startTier(route: Route): Tier {
  if (route.risk === 'high' && route.base_complexity >= 8) return 'advanced';
  if (route.tier === 'hard' || route.tier === 'critical') return 'balanced';
  return 'fast';
}

export function planExecution(task: string, route: Route, cfg: RouterConfig, first: Selection): ExecutionPlan {
  const sc = cfg.stages;
  const tier = startTier(route);
  // the single stage keeps the router's own model/effort unless complexity+risk justify starting higher
  const taskStage = makeStage('task', tier, tier === 'advanced' ? 'high' : first.effort ?? 'medium', tier === 'fast' ? 'straightforward task' : `${route.tier} task (${route.risk} risk)`);
  if (!sc.enabled || sc.execution_strategy === 'direct') return { strategy: 'direct', stages: [taskStage], reviewAfter: false, adaptive: false };
  // plan on the user's request, not on pasted tickets/docs (their headings would look like many deliverables)
  if (route.reference_chars > 0) task = splitPrompt(task).instruction;
  const modifies = MODIFY.test(task);
  const reviewAfter = modifies && route.risk === 'high' && CUE.review.test(task) && sc.max_stages >= 2;
  const deliverables = [CUE.design, CUE.tests, CUE.docs, CUE.migration, CUE.review].filter((re) => re.test(task)).length;
  // several distinct deliverables (design + migrations + tests + docs…), or hard work with a few of them
  const complex = modifies && (deliverables >= 4 || (route.base_complexity >= 7 && deliverables >= 3));
  if ((complex || (sc.execution_strategy === 'orchestrated' && route.base_complexity >= 7 && modifies)) && sc.max_stages >= 2 && CUE.design.test(task)) {
    const implTier: Tier = route.base_complexity >= 9 ? 'balanced' : 'fast';
    return { strategy: 'orchestrated', stages: [makeStage('design', tier === 'advanced' ? 'advanced' : 'balanced'), makeStage('implement', implTier)], reviewAfter, adaptive: true };
  }
  return { strategy: 'adaptive', stages: [taskStage], reviewAfter, adaptive: true };
}

export interface ExecutionContext {
  task: string; completed: string[]; current_stage: string; modified_files: string[]; known_issues: string[]; pending: string[]; constraints: string[];
}

export function analyzeStage(items: TurnItem[] = []): { files: string[]; testsFailed: boolean; stuck: boolean; outcome: string; failures: string[] } {
  const files = [...new Set(items.flatMap((i) => i.files ?? []))];
  // The exit code only reflects the tests when the runner is the LAST command of a chain:
  // `node --test && rg -n x` exits 1 when rg finds nothing, which says nothing about the tests.
  const isTestResult = (cmd: string) => TEST_CMD.test(unwrap(cmd).split(/&&|\|\||;|\|/).pop() ?? '');
  const tests = items.filter((i) => i.type === 'commandExecution' && i.command && isTestResult(i.command));
  const last = tests.at(-1);
  const testsFailed = Boolean(last && typeof last.exitCode === 'number' && last.exitCode !== 0);
  const message = items.filter((i) => i.type === 'agentMessage' && i.text).at(-1)?.text ?? '';
  const failures = testsFailed ? [`tests still failing (exit ${last!.exitCode}) after \`${last!.command!.replace(/^\S*sh -lc /, '').slice(0, 80)}\``] : [];
  return { files, testsFailed, stuck: STUCK.test(message), outcome: message.replace(/\s+/g, ' ').trim().slice(0, 160), failures };
}

export interface RoutingLog {
  level: 'info' | 'warn'; event: string; request_id: string; execution_id: string; stage_id?: string; stage_type?: string;
  previous_model?: string | null; selected_model?: string; routing_reason?: string; escalation_level?: number;
  execution_duration_ms?: number; retry_count?: number; switch_count?: number; routing_strategy: string; status?: string; [k: string]: unknown;
}

export function logRouting(entry: RoutingLog, cfg: RouterConfig): void {
  if (!cfg.analytics.enabled) return;
  try {
    fs.mkdirSync(stateDir(), { recursive: true });
    fs.appendFileSync(path.join(stateDir(), 'routing.jsonl'), `${JSON.stringify({ ts: new Date().toISOString(), ...entry })}\n`);
  } catch { /* logging must never break execution */ }
}

export interface StageHooks {
  /** Called once with the initial plan; `models` are what each stage starts on. */
  planned(plan: ExecutionPlan, models: string[]): void;
  stageStart(stage: Stage, index: number, total: number, sel: Selection, switched?: { from: string; to: string; reason: string }): void;
  stageEnd(stage: Stage, index: number, total: number): void;
  notice(text: string): void;
}

export interface StageDeps {
  cfg: RouterConfig;
  catalog: ModelInfo[];
  /** Runs one turn with an explicit model/effort (the real switch), on the main thread or an isolated one. */
  send(prompt: string, sel: Selection, opts: { first: boolean; isolated: boolean }): Promise<TurnResult>;
  interrupt(): Promise<unknown>;
  cancelled(): boolean;
  /** Main-thread context size (provider-reported), used for isolation/compaction decisions. */
  context?(): { used: number; window: number | null } | undefined;
  compact?(): Promise<boolean>;
  hooks: StageHooks;
  log?: (e: RoutingLog) => void;
  requestId?: string;
  /** Per-request budget: consulted before any additional stage or retry (at boundaries only). */
  budget?: Budget;
}

export interface ExecutionResult {
  status: 'completed' | 'failed' | 'cancelled'; error?: string; stages: Stage[]; strategy: Strategy;
  switches: number; escalations: number; compactions: number; retries: number; usage: TokenBreakdown; usageReported: boolean; ms: number; models: string[];
  /** Set when the budget stopped execution at a boundary: why, and what was left undone. */
  stopped?: { reason: string; unfinished: string[] };
}

export class StagedExecution {
  readonly id = `exec_${randomUUID().slice(0, 12)}`;
  readonly ctx: ExecutionContext;
  readonly stages: Stage[];
  private strategy: Strategy;
  private switches = 0;
  private escalations = 0;
  private compactions = 0;
  private retries = 0;
  private prevModel: string | null = null;
  private prevTier: Tier | null = null;
  private prevEffort: string | undefined;

  constructor(private readonly task: string, readonly plan: ExecutionPlan, private readonly deps: StageDeps, private readonly first: Selection = {}, constraints: string[] = []) {
    this.stages = [...plan.stages];
    this.strategy = plan.strategy;
    this.ctx = { task: task.replace(/\s+/g, ' ').trim().slice(0, 200), completed: [], current_stage: '', modified_files: [], known_issues: [], pending: [], constraints: ['do not redo completed stages', ...constraints] };
  }

  private log(e: Omit<RoutingLog, 'request_id' | 'execution_id' | 'routing_strategy'>): void {
    const entry = { request_id: this.deps.requestId ?? this.id, execution_id: this.id, routing_strategy: this.strategy, switch_count: this.switches, ...e } as RoutingLog;
    (this.deps.log ?? ((x) => logRouting(x, this.deps.cfg)))(entry);
  }

  /** Model for a stage. A plain single task keeps the router's own selection; tiers resolve through the catalog. */
  private select(stage: Stage, tier: Tier, effort: string): Selection & { note?: string } {
    if (stage.type === 'task' && stage.attempts <= 1 && tier === stage.tier && tier !== 'advanced' && this.first.model) return { model: this.first.model, effort: this.first.effort ?? effort };
    const r = resolveModel(this.deps.catalog, this.deps.cfg.stages.tiers[tier], effort, false, this.deps.cfg.stages.tiers.fast);
    return { model: r.model, effort: r.effort, note: r.note };
  }

  /** Shared thread while its history is small; an isolated thread with a compact hand-off once it is large. */
  private isolate(i: number): boolean {
    const mode = this.deps.cfg.stages.context_strategy;
    if (i === 0 || mode === 'shared') return false;
    if (mode === 'isolated') return true;
    const c = this.deps.context?.();
    return Boolean(c && c.used >= this.deps.cfg.stages.isolate_min_context_tokens);
  }

  private prompt(stage: Stage, i: number, isolated: boolean): string {
    if (stage.type === 'task' && stage.attempts <= 1) return this.task; // verbatim: no wrapper overhead on the common path
    this.ctx.current_stage = stage.title;
    this.ctx.pending = this.stages.slice(i + 1).filter((s) => s.status === 'pending').map((s) => s.title);
    const parts = [`[Lumina stage ${i + 1}: ${stage.title}]`, `Handoff: ${JSON.stringify(this.ctx)}`];
    parts.push(`Objective: ${stage.type === 'task' ? 'Complete the user request below; the previous attempt failed (see known_issues). Do not redo work that already succeeded.' : DEF[stage.type].objective}`);
    // a fresh thread knows nothing: give it the request (bounded); on the shared thread the history already has it
    if (isolated || (i === 0)) parts.push(`User request:\n${this.task.slice(0, 4000)}`);
    if (!this.stages.slice(i + 1).some((s) => s.status === 'pending')) parts.push('This is the final stage: finish with a concise summary for the user of everything done.');
    return parts.join('\n\n');
  }

  async run(): Promise<ExecutionResult> {
    const { cfg, hooks } = this.deps;
    const lim = cfg.stages;
    const t0 = Date.now();
    const usage: TokenBreakdown = { totalTokens: 0, inputTokens: 0, cachedInputTokens: 0, outputTokens: 0 };
    let usageReported = false;
    hooks.planned(this.plan, this.stages.map((s) => this.select(s, s.tier, s.effort).model ?? ''));
    this.log({ level: 'info', event: 'plan_created', status: `${this.stages.length} stage(s)`, stage_type: this.stages.map((s) => s.type).join('>'), review_after: this.plan.reviewAfter });
    let failure: string | undefined;
    let status: ExecutionResult['status'] = 'completed';

    for (let i = 0; i < this.stages.length; i++) {
      const stage = this.stages[i];
      if (this.deps.cancelled()) { status = 'cancelled'; break; }
      if (i > 0 && this.deps.budget) { // every stage after the first is additional work: check the budget at this boundary
        const ok = this.deps.budget.allow('stage', this.benefit.get(stage.id) ?? 'high');
        if (!ok.ok) { this.stopForBudget(ok.reason, i); status = 'failed'; failure = `stopped: budget exhausted (${ok.reason})`; break; }
      }
      if (this.deps.budget) this.deps.budget.stages++;
      stage.status = 'running';
      let tier = stage.tier;
      let effort = stage.effort;
      for (;;) {
        stage.attempts++;
        let sel = this.select(stage, tier, effort);
        // switching costs a cold start (no prompt cache) on another model: don't step DOWN just for a final short review
        const last = !this.stages.slice(i + 1).some((s) => s.status === 'pending');
        if (lim.model_switch_penalty && stage.type === 'review' && stage.attempts === 1 && this.prevModel && this.prevTier && sel.model !== this.prevModel && last && TIER_ORDER.indexOf(tier) < TIER_ORDER.indexOf(this.prevTier)) {
          this.log({ level: 'info', event: 'switch_skipped', stage_id: stage.id, stage_type: stage.type, selected_model: this.prevModel, routing_reason: 'model_switch_penalty: final stage stays on the current model' });
          sel = { model: this.prevModel, effort: sel.effort }; tier = this.prevTier;
        }
        let switched: { from: string; to: string; reason: string } | undefined;
        if (this.prevModel && sel.model !== this.prevModel) {
          if (this.switches >= lim.max_switches) {
            this.log({ level: 'warn', event: 'switch_limit_reached', stage_id: stage.id, stage_type: stage.type, selected_model: this.prevModel, routing_reason: `wanted ${sel.model}` });
            sel = { model: this.prevModel, effort: sel.effort };
          } else {
            this.switches++;
            switched = { from: this.prevModel, to: sel.model!, reason: stage.reason };
            this.log({ level: 'info', event: 'model_switched', stage_id: stage.id, stage_type: stage.type, previous_model: this.prevModel, selected_model: sel.model, routing_reason: stage.reason, escalation_level: stage.escalation });
          }
        }
        if (sel.note) this.log({ level: 'warn', event: 'model_fallback', stage_id: stage.id, stage_type: stage.type, selected_model: sel.model, routing_reason: sel.note });
        const isolated = this.isolate(i);
        if (!isolated && i > 0 && lim.compaction_strategy === 'auto' && this.deps.compact) {
          const c = this.deps.context?.();
          if (c?.window && c.used / c.window >= lim.compact_threshold) {
            const ok = await this.deps.compact().catch(() => false);
            if (ok) this.compactions++;
            this.log({ level: ok ? 'info' : 'warn', event: ok ? 'context_compacted' : 'compaction_failed', stage_id: stage.id, routing_reason: `context ${Math.round((c.used / c.window) * 100)}% of window` });
          }
        }
        stage.model = sel.model;
        stage.effort = sel.effort ?? stage.effort; // what was actually sent (after clamping to the model's levels)
        this.prevEffort = stage.effort;
        stage.thread = isolated ? 'isolated' : 'shared';
        hooks.stageStart(stage, i, this.stages.length, sel, switched);
        this.log({ level: 'info', event: 'stage_started', stage_id: stage.id, stage_type: stage.type, previous_model: this.prevModel, selected_model: sel.model, routing_reason: stage.reason, escalation_level: stage.escalation, retry_count: stage.attempts - 1, context: stage.thread });
        const st = Date.now();
        this.deps.budget?.beginTurn();
        let result: TurnResult;
        try {
          result = await this.withTimeout(this.deps.send(this.prompt(stage, i, isolated), { model: sel.model, effort: sel.effort }, { first: i === 0 && stage.attempts === 1, isolated }), lim.stage_timeout_ms);
        } catch (e) {
          result = { status: 'failed', error: e instanceof Error ? e.message : String(e) };
        }
        stage.ms = (stage.ms ?? 0) + Date.now() - st;
        this.deps.budget?.turn(result.usage);
        if (result.usage) {
          usageReported = true;
          stage.usage = add(stage.usage, result.usage);
          for (const k of Object.keys(usage) as (keyof TokenBreakdown)[]) usage[k] += result.usage[k];
        }
        this.prevModel = sel.model ?? this.prevModel;
        this.prevTier = tier;
        const sig = analyzeStage(result.items);
        for (const f of sig.files) if (!this.ctx.modified_files.includes(f)) this.ctx.modified_files.push(f);
        this.ctx.modified_files = this.ctx.modified_files.slice(-30);

        if (result.status === 'interrupted' || this.deps.cancelled()) { stage.status = 'skipped'; stage.outcome = 'cancelled'; status = 'cancelled'; break; }
        if (result.status === 'failed') {
          const kind = classifyFailure(result.error ?? '');
          const rejectedModel = /model/i.test(result.error ?? '') && /(not (supported|available)|unsupported|unknown|invalid)/i.test(result.error ?? '');
          if (this.plan.adaptive && rejectedModel && sel.model !== cfg.stages.tiers.fast && stage.attempts <= lim.max_retries) {
            this.log({ level: 'warn', event: 'model_rejected', stage_id: stage.id, stage_type: stage.type, selected_model: sel.model, routing_reason: 'backend rejected model; falling back' });
            tier = 'fast'; this.retries++; continue;
          }
          const retryOk = this.deps.budget ? this.deps.budget.allow('stage', 'high') : { ok: true as const };
          if (!retryOk.ok && this.plan.adaptive && kind === 'coding') { this.stopForBudget(retryOk.reason, i + 1, [`retry ${stage.title}`]); stage.status = 'failed'; stage.outcome = (result.error ?? 'failed').slice(0, 160); failure = `stopped: budget exhausted (${retryOk.reason}); ${stage.title} failed: ${stage.outcome}`; status = 'failed'; break; }
          if (this.plan.adaptive && kind === 'coding' && stage.attempts <= lim.max_retries && this.escalations < lim.max_escalations && tier !== 'advanced') {
            tier = TIER_ORDER[TIER_ORDER.indexOf(tier) + 1]; effort = raiseEffort(effort, 'high'); stage.escalation++; this.escalations++; this.retries++;
            this.strategy = this.strategy === 'direct' ? 'adaptive' : this.strategy;
            this.ctx.known_issues = [`previous attempt failed: ${(result.error ?? 'failed').slice(0, 160)}`];
            this.log({ level: 'warn', event: 'escalated', stage_id: stage.id, stage_type: stage.type, selected_model: this.select(stage, tier, effort).model, routing_reason: 'stage failed', escalation_level: stage.escalation, retry_count: stage.attempts });
            hooks.notice(`stage failed; retrying ${stage.title} on a stronger model`);
            continue;
          }
          stage.status = 'failed'; stage.outcome = (result.error ?? 'failed').slice(0, 160);
          failure = `${stage.title} failed${kind !== 'coding' ? ` (${kind})` : ''}: ${stage.outcome}`;
          status = 'failed';
          break;
        }
        stage.status = 'done';
        stage.outcome = sig.outcome;
        this.ctx.completed.push(`${stage.title}: ${sig.outcome || 'done'}`.slice(0, 200));
        if (sig.failures.length) this.ctx.known_issues.push(...sig.failures);
        this.ctx.known_issues = this.ctx.known_issues.slice(-5);
        const problem = sig.testsFailed || (sig.stuck && ['task', 'implement', 'fix'].includes(stage.type));
        if (problem && this.plan.adaptive) {
          // lazy stage: the first fix moves one tier up; a later one first reasons deeper on the same model (keeps its
          // prompt cache) and only changes model once reasoning cannot go higher
          const fixes = this.stages.filter((s) => s.type === 'fix').length;
          const deeper = fixes >= 1 && raiseEffort(this.prevEffort ?? effort, 'xhigh') !== (this.prevEffort ?? effort);
          const nextTier = deeper ? tier : TIER_ORDER[Math.min(TIER_ORDER.indexOf(tier) + 1, 2)];
          // a fix stage must be worth it: failing tests are a verified problem; "could not resolve" is less certain
          const benefit: Benefit = sig.testsFailed ? 'high' : 'medium';
          const room = this.deps.budget ? this.deps.budget.allow('stage', benefit) : { ok: true as const };
          if (!room.ok) {
            this.stopForBudget(room.reason, i + 1, [sig.testsFailed ? 'fix the failing tests' : 'resolve the reported problem']);
            failure = `stopped: budget exhausted (${room.reason}); ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed';
          } else if (fixes < lim.max_retries && this.escalations < lim.max_escalations && this.stages.length < lim.max_stages + lim.max_escalations) {
            // reasoning one step above what failed (at least medium); a second fix may go beyond high
            const fixEffort = raiseEffort(this.prevEffort ?? effort, fixes >= 1 ? 'xhigh' : 'high');
            const fix = makeStage('fix', nextTier, fixEffort, sig.testsFailed ? 'tests still failing after previous stage' : 'previous stage reported it could not resolve the problem');
            fix.escalation = TIER_ORDER.indexOf(nextTier);
            this.escalations++;
            this.strategy = this.strategy === 'direct' ? 'adaptive' : this.strategy;
            this.stages.splice(i + 1, 0, fix);
            this.benefit.set(fix.id, benefit);
            this.log({ level: 'warn', event: 'escalated', stage_id: fix.id, stage_type: 'fix', selected_model: this.select(fix, nextTier, fixEffort).model, reasoning_effort: fixEffort, routing_reason: fix.reason, escalation_level: fix.escalation });
          } else {
            this.log({ level: 'warn', event: 'escalation_limit_reached', stage_id: stage.id, stage_type: stage.type, routing_reason: 'problems remain' });
            failure = `${stage.title}: ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed';
          }
        } else if (problem) {
          failure = `${stage.title}: ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed';
        } else if (stage.type === 'fix') this.ctx.known_issues = [];
        break;
      }
      hooks.stageEnd(stage, i, this.stages.length);
      this.log({ level: stage.status === 'failed' ? 'warn' : 'info', event: 'stage_completed', stage_id: stage.id, stage_type: stage.type, selected_model: stage.model, status: stage.status, execution_duration_ms: stage.ms, retry_count: stage.attempts - 1, escalation_level: stage.escalation, context: stage.thread, ...flat(stage.usage) });
      if (status !== 'completed') break;
      // lazy review: only after the work is otherwise complete, and only if something was actually changed
      const remaining = this.stages.slice(i + 1).some((s) => s.status === 'pending');
      if (!remaining && this.plan.reviewAfter && this.ctx.modified_files.length && !this.stages.some((s) => s.type === 'review')) {
        this.stages.push(makeStage('review'));
        this.strategy = this.strategy === 'direct' ? 'adaptive' : this.strategy;
        this.log({ level: 'info', event: 'stage_added', stage_type: 'review', routing_reason: 'high-risk change with requested review' });
      }
    }
    for (const s of this.stages) if (s.status === 'pending') s.status = 'skipped';
    if (this.deps.budget) { this.deps.budget.escalations = this.escalations; this.deps.budget.switches = this.switches; }
    const result: ExecutionResult = {
      status, error: failure, stages: this.stages, strategy: this.strategy, switches: this.switches, escalations: this.escalations,
      compactions: this.compactions, retries: this.retries, usage, usageReported, ms: Date.now() - t0,
      models: [...new Set(this.stages.map((s) => s.model).filter((m): m is string => Boolean(m)))],
      ...(this.deps.budget?.stopped ? { stopped: this.deps.budget.stopped } : {}),
    };
    this.log({ level: status === 'completed' ? 'info' : 'warn', event: 'execution_finished', status, stages: this.stages.filter((s) => s.status !== 'skipped').length, models: result.models.join(','), escalation_level: this.escalations, compactions: this.compactions, retry_count: this.retries, execution_duration_ms: result.ms, token_source: usageReported ? 'provider' : 'unavailable', ...(usageReported ? flat(usage) : {}) });
    return result;
  }

  /** Expected benefit of lazily added stages (fix stages after verified failures are "high"). */
  private benefit = new Map<string, Benefit>();

  /** Budget exhausted at a boundary: remaining stages are left undone and reported, never marked done. */
  private stopForBudget(reason: string, from: number, extra: string[] = []): void {
    const unfinished = [...extra, ...this.stages.slice(from).filter((s) => s.status === 'pending').map((s) => s.title)];
    this.deps.budget?.stop(reason, unfinished.length ? unfinished : ['no remaining planned stages']);
    this.log({ level: 'warn', event: 'budget_exhausted', routing_reason: reason, status: unfinished.join('; ') });
    this.deps.hooks.notice(`budget exhausted: ${reason} — stopping here`);
  }

  private withTimeout(p: Promise<TurnResult>, ms: number): Promise<TurnResult> {
    let timer: NodeJS.Timeout | undefined;
    const timeout = new Promise<TurnResult>((resolve) => {
      timer = setTimeout(() => {
        void this.deps.interrupt().catch(() => undefined);
        resolve({ status: 'failed', error: `stage timed out after ${Math.round(ms / 1000)}s` });
      }, ms);
      timer.unref?.();
    });
    return Promise.race([p, timeout]).finally(() => clearTimeout(timer));
  }
}

constructor(private readonly task: string, readonly plan: ExecutionPlan, private readonly deps: StageDeps, private readonly first: Selection = {}, constraints: string[] = []) {
  this.stages = [...plan.stages];
  this.strategy = plan.strategy;
  this.ctx = { task: task.replace(/\s+/g, ' ').trim().slice(0, 200), completed: [], current_stage: '', modified_files: [], known_issues: [], pending: [], constraints: ['do not redo completed stages', ...constraints] };
}

private log(e: Omit<RoutingLog, 'request_id' | 'execution_id' | 'routing_strategy'>): void {
  const entry = { request_id: this.deps.requestId ?? this.id, execution_id: this.id, routing_strategy: this.strategy, switch_count: this.switches, ...e } as RoutingLog;
  (this.deps.log ?? ((x) => logRouting(x, this.deps.cfg)))(entry);
}

private select(stage: Stage, tier: Tier, effort: string): Selection & { note?: string } {
  if (stage.type === 'task' && stage.attempts <= 1 && tier === stage.tier && tier !== 'advanced' && this.first.model) return { model: this.first.model, effort: this.first.effort ?? effort };
  const r = resolveModel(this.deps.catalog, this.deps.cfg.stages.tiers[tier], effort, false, this.deps.cfg.stages.tiers.fast);
  return { model: r.model, effort: r.effort, note: r.note };
}

private isolate(i: number): boolean {
  const mode = this.deps.cfg.stages.context_strategy;
  if (i === 0 || mode === 'shared') return false;
  if (mode === 'isolated') return true;
  const c = this.deps.context?.();
  return Boolean(c && c.used >= this.deps.cfg.stages.isolate_min_context_tokens);
}

private prompt(stage: Stage, i: number, isolated: boolean): string {
  if (stage.type === 'task' && stage.attempts <= 1) return this.task; // verbatim: no wrapper overhead on the common path
  this.ctx.current_stage = stage.title;
  this.ctx.pending = this.stages.slice(i + 1).filter((s) => s.status === 'pending').map((s) => s.title);
  const parts = [`[Lumina stage ${i + 1}: ${stage.title}]`, `Handoff: ${JSON.stringify(this.ctx)}`];
  parts.push(`Objective: ${stage.type === 'task' ? 'Complete the user request below; the previous attempt failed (see known_issues). Do not redo work that already succeeded.' : DEF[stage.type].objective}`);
  // a fresh thread knows nothing: give it the request (bounded); on the shared thread the history already has it
  if (isolated || (i === 0)) parts.push(`User request:\n${this.task.slice(0, 4000)}`);
  if (!this.stages.slice(i + 1).some((s) => s.status === 'pending')) parts.push('This is the final stage: finish with a concise summary for the user of everything done.');
  return parts.join('\n\n');
}

async run(): Promise<ExecutionResult> {
  const { cfg, hooks } = this.deps;
  const lim = cfg.stages;
  const t0 = Date.now();
  const usage: TokenBreakdown = { totalTokens: 0, inputTokens: 0, cachedInputTokens: 0, outputTokens: 0 };
  let usageReported = false;
  hooks.planned(this.plan, this.stages.map((s) => this.select(s, s.tier, s.effort).model ?? ''));
  this.log({ level: 'info', event: 'plan_created', status: `${this.stages.length} stage(s)`, stage_type: this.stages.map((s) => s.type).join('>'), review_after: this.plan.reviewAfter });
  let failure: string | undefined;
  let status: ExecutionResult['status'] = 'completed';

  for (let i = 0; i < this.stages.length; i++) {
    const stage = this.stages[i];
    if (this.deps.cancelled()) { status = 'cancelled'; break; }
    if (i > 0 && this.deps.budget) { // every stage after the first is additional work: check the budget at this boundary
      const ok = this.deps.budget.allow('stage', this.benefit.get(stage.id) ?? 'high');
      if (!ok.ok) { this.stopForBudget(ok.reason, i); status = 'failed'; failure = `stopped: budget exhausted (${ok.reason})`; break; }
    }
    if (this.deps.budget) this.deps.budget.stages++;
    stage.status = 'running';
    let tier = stage.tier;
    let effort = stage.effort;
    for (;;) {
      stage.attempts++;
      let sel = this.select(stage, tier, effort);
      // switching costs a cold start (no prompt cache) on another model: don't step DOWN just for a final short review
      const last = !this.stages.slice(i + 1).some((s) => s.status === 'pending');
      if (lim.model_switch_penalty && stage.type === 'review' && stage.attempts === 1 && this.prevModel && this.prevTier && sel.model !== this.prevModel && last && TIER_ORDER.indexOf(tier) < TIER_ORDER.indexOf(this.prevTier)) {
        this.log({ level: 'info', event: 'switch_skipped', stage_id: stage.id, stage_type: stage.type, selected_model: this.prevModel, routing_reason: 'model_switch_penalty: final stage stays on the current model' });
        sel = { model: this.prevModel, effort: sel.effort }; tier = this.prevTier;
      }
      let switched: { from: string; to: string; reason: string } | undefined;
      if (this.prevModel && sel.model !== this.prevModel) {
        if (this.switches >= lim.max_switches) {
          this.log({ level: 'warn', event: 'switch_limit_reached', stage_id: stage.id, stage_type: stage.type, selected_model: this.prevModel, routing_reason: `wanted ${sel.model}` });
          sel = { model: this.prevModel, effort: sel.effort };
        } else {
          this.switches++;
          switched = { from: this.prevModel, to: sel.model!, reason: stage.reason };
          this.log({ level: 'info', event: 'model_switched', stage_id: stage.id, stage_type: stage.type, previous_model: this.prevModel, selected_model: sel.model, routing_reason: stage.reason, escalation_level: stage.escalation });
        }
      }
      if (sel.note) this.log({ level: 'warn', event: 'model_fallback', stage_id: stage.id, stage_type: stage.type, selected_model: sel.model, routing_reason: sel.note });
      const isolated = this.isolate(i);
      if (!isolated && i > 0 && lim.compaction_strategy === 'auto' && this.deps.compact) {
        const c = this.deps.context?.();
        if (c?.window && c.used / c.window >= lim.compact_threshold) {
          const ok = await this.deps.compact().catch(() => false);
          if (ok) this.compactions++;
          this.log({ level: ok ? 'info' : 'warn', event: ok ? 'context_compacted' : 'compaction_failed', stage_id: stage.id, routing_reason: `context ${Math.round((c.used / c.window) * 100)}% of window` });
        }
      }
      stage.model = sel.model;
      stage.effort = sel.effort ?? stage.effort; // what was actually sent (after clamping to the model's levels)
      this.prevEffort = stage.effort;
      stage.thread = isolated ? 'isolated' : 'shared';
      hooks.stageStart(stage, i, this.stages.length, sel, switched);
      this.log({ level: 'info', event: 'stage_started', stage_id: stage.id, stage_type: stage.type, previous_model: this.prevModel, selected_model: sel.model, routing_reason: stage.reason, escalation_level: stage.escalation, retry_count: stage.attempts - 1, context: stage.thread });
      const st = Date.now();
      this.deps.budget?.beginTurn();
      let result: TurnResult;
      try {
        result = await this.withTimeout(this.deps.send(this.prompt(stage, i, isolated), { model: sel.model, effort: sel.effort }, { first: i === 0 && stage.attempts === 1, isolated }), lim.stage_timeout_ms);
      } catch (e) {
        result = { status: 'failed', error: e instanceof Error ? e.message : String(e) };
      }
      stage.ms = (stage.ms ?? 0) + Date.now() - st;
      this.deps.budget?.turn(result.usage);
      if (result.usage) {
        usageReported = true;
        stage.usage = add(stage.usage, result.usage);
        for (const k of Object.keys(usage) as (keyof TokenBreakdown)[]) usage[k] += result.usage[k];
      }
      this.prevModel = sel.model ?? this.prevModel;
      this.prevTier = tier;
      const sig = analyzeStage(result.items);
      for (const f of sig.files) if (!this.ctx.modified_files.includes(f)) this.ctx.modified_files.push(f);
      this.ctx.modified_files = this.ctx.modified_files.slice(-30);

      if (result.status === 'interrupted' || this.deps.cancelled()) { stage.status = 'skipped'; stage.outcome = 'cancelled'; status = 'cancelled'; break; }
      if (result.status === 'failed') {
        const kind = classifyFailure(result.error ?? '');
        const rejectedModel = /model/i.test(result.error ?? '') && /(not (supported|available)|unsupported|unknown|invalid)/i.test(result.error ?? '');
        if (this.plan.adaptive && rejectedModel && sel.model !== cfg.stages.tiers.fast && stage.attempts <= lim.max_retries) {
          this.log({ level: 'warn', event: 'model_rejected', stage_id: stage.id, stage_type: stage.type, selected_model: sel.model, routing_reason: 'backend rejected model; falling back' });
          tier = 'fast'; this.retries++; continue;
        }
        const retryOk = this.deps.budget ? this.deps.budget.allow('stage', 'high') : { ok: true as const };
        if (!retryOk.ok && this.plan.adaptive && kind === 'coding') { this.stopForBudget(retryOk.reason, i + 1, [`retry ${stage.title}`]); stage.status = 'failed'; stage.outcome = (result.error ?? 'failed').slice(0, 160); failure = `stopped: budget exhausted (${retryOk.reason}); ${stage.title} failed: ${stage.outcome}`; status = 'failed'; break; }
        if (this.plan.adaptive && kind === 'coding' && stage.attempts <= lim.max_retries && this.escalations < lim.max_escalations && tier !== 'advanced') {
          tier = TIER_ORDER[TIER_ORDER.indexOf(tier) + 1]; effort = raiseEffort(effort, 'high'); stage.escalation++; this.escalations++; this.retries++;
          this.strategy = this.strategy === 'direct' ? 'adaptive' : this.strategy;
          this.ctx.known_issues = [`previous attempt failed: ${(result.error ?? 'failed').slice(0, 160)}`];
          this.log({ level: 'warn', event: 'escalated', stage_id: stage.id, stage_type: stage.type, selected_model: this.select(stage, tier, effort).model, routing_reason: 'stage failed', escalation_level: stage.escalation, retry_count: stage.attempts });
          hooks.notice(`stage failed; retrying ${stage.title} on a stronger model`);
          continue;
        }
        stage.status = 'failed'; stage.outcome = (result.error ?? 'failed').slice(0, 160);
        failure = `${stage.title} failed${kind !== 'coding' ? ` (${kind})` : ''}: ${stage.outcome}`;
        status = 'failed';
        break;
      }
      stage.status = 'done';
      stage.outcome = sig.outcome;
      this.ctx.completed.push(`${stage.title}: ${sig.outcome || 'done'}`.slice(0, 200));
      if (sig.failures.length) this.ctx.known_issues.push(...sig.failures);
      this.ctx.known_issues = this.ctx.known_issues.slice(-5);
      const problem = sig.testsFailed || (sig.stuck && ['task', 'implement', 'fix'].includes(stage.type));
      if (problem && this.plan.adaptive) {
        // lazy stage: the first fix moves one tier up; a later one first reasons deeper on the same model (keeps its
        // prompt cache) and only changes model once reasoning cannot go higher
        const fixes = this.stages.filter((s) => s.type === 'fix').length;
        const deeper = fixes >= 1 && raiseEffort(this.prevEffort ?? effort, 'xhigh') !== (this.prevEffort ?? effort);
        const nextTier = deeper ? tier : TIER_ORDER[Math.min(TIER_ORDER.indexOf(tier) + 1, 2)];
        // a fix stage must be worth it: failing tests are a verified problem; "could not resolve" is less certain
        const benefit: Benefit = sig.testsFailed ? 'high' : 'medium';
        const room = this.deps.budget ? this.deps.budget.allow('stage', benefit) : { ok: true as const };
        if (!room.ok) {
          this.stopForBudget(room.reason, i + 1, [sig.testsFailed ? 'fix the failing tests' : 'resolve the reported problem']);
          failure = `stopped: budget exhausted (${room.reason}); ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed';
        } else if (fixes < lim.max_retries && this.escalations < lim.max_escalations && this.stages.length < lim.max_stages + lim.max_escalations) {
          // reasoning one step above what failed (at least medium); a second fix may go beyond high
          const fixEffort = raiseEffort(this.prevEffort ?? effort, fixes >= 1 ? 'xhigh' : 'high');
          const fix = makeStage('fix', nextTier, fixEffort, sig.testsFailed ? 'tests still failing after previous stage' : 'previous stage reported it could not resolve the problem');
          fix.escalation = TIER_ORDER.indexOf(nextTier);
          this.escalations++;
          this.strategy = this.strategy === 'direct' ? 'adaptive' : this.strategy;
          this.stages.splice(i + 1, 0, fix);
          this.benefit.set(fix.id, benefit);
          this.log({ level: 'warn', event: 'escalated', stage_id: fix.id, stage_type: 'fix', selected_model: this.select(fix, nextTier, fixEffort).model, reasoning_effort: fixEffort, routing_reason: fix.reason, escalation_level: fix.escalation });
        } else {
          this.log({ level: 'warn', event: 'escalation_limit_reached', stage_id: stage.id, stage_type: stage.type, routing_reason: 'problems remain' });
          failure = `${stage.title}: ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed';
        }
      } else if (problem) {
        failure = `${stage.title}: ${sig.failures[0] ?? 'problem unresolved'}`; status = 'failed';
      } else if (stage.type === 'fix') this.ctx.known_issues = [];
      break;
    }
    hooks.stageEnd(stage, i, this.stages.length);
    this.log({ level: stage.status === 'failed' ? 'warn' : 'info', event: 'stage_completed', stage_id: stage.id, stage_type: stage.type, selected_model: stage.model, status: stage.status, execution_duration_ms: stage.ms, retry_count: stage.attempts - 1, escalation_level: stage.escalation, context: stage.thread, ...flat(stage.usage) });
    if (status !== 'completed') break;
    // lazy review: only after the work is otherwise complete, and only if something was actually changed
    const remaining = this.stages.slice(i + 1).some((s) => s.status === 'pending');
    if (!remaining && this.plan.reviewAfter && this.ctx.modified_files.length && !this.stages.some((s) => s.type === 'review')) {
      this.stages.push(makeStage('review'));
      this.strategy = this.strategy === 'direct' ? 'adaptive' : this.strategy;
      this.log({ level: 'info', event: 'stage_added', stage_type: 'review', routing_reason: 'high-risk change with requested review' });
    }
  }
  for (const s of this.stages) if (s.status === 'pending') s.status = 'skipped';
  if (this.deps.budget) { this.deps.budget.escalations = this.escalations; this.deps.budget.switches = this.switches; }
  const result: ExecutionResult = {
    status, error: failure, stages: this.stages, strategy: this.strategy, switches: this.switches, escalations: this.escalations,
    compactions: this.compactions, retries: this.retries, usage, usageReported, ms: Date.now() - t0,
    models: [...new Set(this.stages.map((s) => s.model).filter((m): m is string => Boolean(m)))],
    ...(this.deps.budget?.stopped ? { stopped: this.deps.budget.stopped } : {}),
  };
  this.log({ level: status === 'completed' ? 'info' : 'warn', event: 'execution_finished', status, stages: this.stages.filter((s) => s.status !== 'skipped').length, models: result.models.join(','), escalation_level: this.escalations, compactions: this.compactions, retry_count: this.retries, execution_duration_ms: result.ms, token_source: usageReported ? 'provider' : 'unavailable', ...(usageReported ? flat(usage) : {}) });
  return result;
}

const result: ExecutionResult = {
  status, error: failure, stages: this.stages, strategy: this.strategy, switches: this.switches, escalations: this.escalations,
  compactions: this.compactions, retries: this.retries, usage, usageReported, ms: Date.now() - t0,
  models: [...new Set(this.stages.map((s) => s.model).filter((m): m is string => Boolean(m)))],
  ...(this.deps.budget?.stopped ? { stopped: this.deps.budget.stopped } : {}),
};

private stopForBudget(reason: string, from: number, extra: string[] = []): void {
  const unfinished = [...extra, ...this.stages.slice(from).filter((s) => s.status === 'pending').map((s) => s.title)];
  this.deps.budget?.stop(reason, unfinished.length ? unfinished : ['no remaining planned stages']);
  this.log({ level: 'warn', event: 'budget_exhausted', routing_reason: reason, status: unfinished.join('; ') });
  this.deps.hooks.notice(`budget exhausted: ${reason} — stopping here`);
}

private withTimeout(p: Promise<TurnResult>, ms: number): Promise<TurnResult> {
  let timer: NodeJS.Timeout | undefined;
  const timeout = new Promise<TurnResult>((resolve) => {
    timer = setTimeout(() => {
      void this.deps.interrupt().catch(() => undefined);
      resolve({ status: 'failed', error: `stage timed out after ${Math.round(ms / 1000)}s` });
    }, ms);
    timer.unref?.();
  });
  return Promise.race([p, timeout]).finally(() => clearTimeout(timer));
}

const timeout = new Promise<TurnResult>((resolve) => {
  timer = setTimeout(() => {
    void this.deps.interrupt().catch(() => undefined);
    resolve({ status: 'failed', error: `stage timed out after ${Math.round(ms / 1000)}s` });
  }, ms);
  timer.unref?.();
});

const timeout = new Promise<TurnResult>((resolve) => {
  timer = setTimeout(() => {
    void this.deps.interrupt().catch(() => undefined);
    resolve({ status: 'failed', error: `stage timed out after ${Math.round(ms / 1000)}s` });
  }, ms);
  timer.unref?.();
});

timer = setTimeout(() => {
  void this.deps.interrupt().catch(() => undefined);
  resolve({ status: 'failed', error: `stage timed out after ${Math.round(ms / 1000)}s` });
}, ms);

export function findTicket(text: string): TicketRef | undefined {
  let m = /\bOP-(\d+)\b/i.exec(text) ?? /\b(?:openproject|work ?package|wp)\s*#?\s*(\d+)\b/i.exec(text);
  if (m) return { id: `OP-${m[1]}`, source: 'openproject', workPackage: m[1] };
  // KEY-123 only counts as a ticket when the text talks about one (avoids UTF-8, SHA-256, ES-2022…)
  m = /\b([A-Z][A-Z0-9]{1,9}-\d+)\b/.exec(text);
  if (m && /\b(tiket|ticket|issue|jira|story|task|card)\b/i.test(text)) return { id: m[1], source: 'jira' };
  return undefined;
}

export function classifyIntent(text: string, active: boolean): TicketIntent | undefined {
  const req = splitPrompt(text).instruction;
  const implement = IMPLEMENT.test(req);
  const understand = UNDERSTAND.test(req);
  if (active && CONFIRM.test(req) && implement) return 'confirm';
  if (understand && !(implement && /\b(lalu|then|and then|setelah itu|kemudian)\b/i.test(req))) return active && !findTicket(req) ? 'clarify' : 'understand';
  if (implement) return active ? 'confirm' : 'implement';
  if (active) return 'clarify'; // anything else during a ticket discussion stays read-only
  return undefined;
}

export interface TicketTurn {
  intent: TicketIntent;
  /** Prompt actually sent to Codex. */
  prompt: string;
  /** Text the router should judge (never the pasted ticket body for understanding). */
  routeText: string;
  /** Run this turn in a read-only sandbox (understanding / clarification). */
  readOnly: boolean;
}

export class TicketSession {
  ticket?: TicketRef;
  mode?: TicketMode;
  clarifications: string[] = [];
  fetched = false;
  summary = '';

  get active(): boolean { return Boolean(this.ticket) && (this.mode === 'understanding' || this.mode === 'ready'); }

  reset(): void { this.ticket = undefined; this.mode = undefined; this.clarifications = []; this.fetched = false; this.summary = ''; }

  private source(): string {
    const t = this.ticket!;
    if (t.source === 'openproject') {
      return this.fetched
        ? `Use the details of OpenProject work package ${t.workPackage} already in this conversation; do not fetch it again unless I ask for fresh data.`
        : `Fetch OpenProject work package ${t.workPackage} once with the lumina-mcp tool get_openproject_work_package.`;
    }
    if (t.source === 'jira') return this.fetched ? `Use the details of ${t.id} already in this conversation.` : `Fetch ${t.id} once with the lumina-mcp tool get_jira_ticket.`;
    return 'The ticket text is the one I pasted.';
  }

  private confirmed(): string {
    return this.clarifications.length ? `Clarifications I gave (they override the original ticket):\n${this.clarifications.map((c, i) => `${i + 1}. ${c}`).join('\n')}` : 'No clarifications: the ticket as written is confirmed.';
  }

  /** Returns how to run this message, or undefined when it is not part of a ticket workflow. */
  prepare(text: string): TicketTurn | undefined {
    const req = splitPrompt(text).instruction;
    const mentioned = findTicket(req);
    const pasted = Boolean(splitPrompt(text).reference);
    const intent = classifyIntent(text, this.active && !(mentioned && mentioned.id !== this.ticket?.id));
    if (!intent) return undefined;

    if (intent === 'understand') {
      this.reset();
      this.ticket = mentioned ?? (pasted ? { id: 'pasted ticket', source: 'pasted' } : undefined);
      if (!this.ticket) return undefined; // "explain X" without a ticket: ordinary question
      this.mode = 'understanding';
      return {
        intent, readOnly: true, routeText: req,
        prompt: `${text}\n\n[Lumina: understanding mode for ${this.ticket.id}. ${this.source()} ${READ_ONLY_RULES} Reply concisely with: 1) what the ticket asks, 2) expected behaviour, 3) relevant components/files, 4) implementation considerations, 5) missing or ambiguous requirements. Mark what is stated in the ticket vs your assumptions; do not invent requirements.]`,
      };
    }
    if (intent === 'clarify') {
      this.clarifications.push(req.trim().slice(0, 600));
      this.mode = 'ready';
      return {
        intent, readOnly: true, routeText: req,
        prompt: `${text}\n\n[Lumina: clarification for ${this.ticket!.id} — update your understanding with this, briefly restate the changed requirement(s) and any remaining open questions. ${this.source()} ${READ_ONLY_RULES} Do not start implementing.]`,
      };
    }
    // implement / confirm
    const fromDiscussion = intent === 'confirm' && this.ticket;
    if (!fromDiscussion) {
      // direct implementation request: no confirmation step forced
      this.reset();
      this.ticket = mentioned ?? (pasted ? { id: 'pasted ticket', source: 'pasted' } : undefined);
      if (!this.ticket) return undefined;
      this.mode = 'implementing';
      return { intent: 'implement', readOnly: false, routeText: text, prompt: text };
    }
    this.mode = 'implementing';
    return {
      intent, readOnly: false,
      // re-route on what will actually be built: the understanding summary + the user's corrections
      routeText: `${req}\n${this.clarifications.join('\n')}\n${this.summary}`,
      prompt: `${text}\n\n[Lumina: implement ${this.ticket!.id} now using the confirmed requirements. ${this.source()} ${this.confirmed()}]`,
    };
  }

  /** After a turn: remember the explanation (compact) and whether the ticket was fetched. */
  afterTurn(answer: string, tools: string[], ok: boolean): void {
    if (!this.ticket) return;
    if (tools.some((t) => /^get_(openproject_work_package|jira_ticket)$/.test(t))) this.fetched = true;
    if (this.mode === 'understanding' || this.mode === 'ready') { if (answer.trim()) this.summary = answer.replace(/\s+/g, ' ').trim().slice(0, 1500); }
    else if (this.mode === 'implementing' && ok) this.mode = 'done';
  }
}

private source(): string {
  const t = this.ticket!;
  if (t.source === 'openproject') {
    return this.fetched
      ? `Use the details of OpenProject work package ${t.workPackage} already in this conversation; do not fetch it again unless I ask for fresh data.`
      : `Fetch OpenProject work package ${t.workPackage} once with the lumina-mcp tool get_openproject_work_package.`;
  }
  if (t.source === 'jira') return this.fetched ? `Use the details of ${t.id} already in this conversation.` : `Fetch ${t.id} once with the lumina-mcp tool get_jira_ticket.`;
  return 'The ticket text is the one I pasted.';
}

private confirmed(): string {
  return this.clarifications.length ? `Clarifications I gave (they override the original ticket):\n${this.clarifications.map((c, i) => `${i + 1}. ${c}`).join('\n')}` : 'No clarifications: the ticket as written is confirmed.';
}

prepare(text: string): TicketTurn | undefined {
  const req = splitPrompt(text).instruction;
  const mentioned = findTicket(req);
  const pasted = Boolean(splitPrompt(text).reference);
  const intent = classifyIntent(text, this.active && !(mentioned && mentioned.id !== this.ticket?.id));
  if (!intent) return undefined;

  if (intent === 'understand') {
    this.reset();
    this.ticket = mentioned ?? (pasted ? { id: 'pasted ticket', source: 'pasted' } : undefined);
    if (!this.ticket) return undefined; // "explain X" without a ticket: ordinary question
    this.mode = 'understanding';
    return {
      intent, readOnly: true, routeText: req,
      prompt: `${text}\n\n[Lumina: understanding mode for ${this.ticket.id}. ${this.source()} ${READ_ONLY_RULES} Reply concisely with: 1) what the ticket asks, 2) expected behaviour, 3) relevant components/files, 4) implementation considerations, 5) missing or ambiguous requirements. Mark what is stated in the ticket vs your assumptions; do not invent requirements.]`,
    };
  }
  if (intent === 'clarify') {
    this.clarifications.push(req.trim().slice(0, 600));
    this.mode = 'ready';
    return {
      intent, readOnly: true, routeText: req,
      prompt: `${text}\n\n[Lumina: clarification for ${this.ticket!.id} — update your understanding with this, briefly restate the changed requirement(s) and any remaining open questions. ${this.source()} ${READ_ONLY_RULES} Do not start implementing.]`,
    };
  }
  // implement / confirm
  const fromDiscussion = intent === 'confirm' && this.ticket;
  if (!fromDiscussion) {
    // direct implementation request: no confirmation step forced
    this.reset();
    this.ticket = mentioned ?? (pasted ? { id: 'pasted ticket', source: 'pasted' } : undefined);
    if (!this.ticket) return undefined;
    this.mode = 'implementing';
    return { intent: 'implement', readOnly: false, routeText: text, prompt: text };
  }
  this.mode = 'implementing';
  return {
    intent, readOnly: false,
    // re-route on what will actually be built: the understanding summary + the user's corrections
    routeText: `${req}\n${this.clarifications.join('\n')}\n${this.summary}`,
    prompt: `${text}\n\n[Lumina: implement ${this.ticket!.id} now using the confirmed requirements. ${this.source()} ${this.confirmed()}]`,
  };
}

afterTurn(answer: string, tools: string[], ok: boolean): void {
  if (!this.ticket) return;
  if (tools.some((t) => /^get_(openproject_work_package|jira_ticket)$/.test(t))) this.fetched = true;
  if (this.mode === 'understanding' || this.mode === 'ready') { if (answer.trim()) this.summary = answer.replace(/\s+/g, ' ').trim().slice(0, 1500); }
  else if (this.mode === 'implementing' && ok) this.mode = 'done';
}

export function readingSelection(route: Route, text: string, ticket: Pick<TicketSession, 'ticket' | 'fetched'>, catalog: ModelInfo[], cfg: RouterConfig): { model: string; effort: string } {
  const tier = route.base_complexity >= 7 ? 'balanced' : 'fast';
  const effort = tier === 'balanced' || splitPrompt(text).reference.length > 2000 || (ticket.ticket?.source !== 'pasted' && !ticket.fetched) ? 'medium' : 'low';
  const r = resolveModel(catalog, cfg.stages.tiers[tier], effort, false, cfg.stages.tiers.fast);
  return { model: r.model, effort: r.effort };
}

const LABEL: Record<Kind, string> = {
  read: 'Reading files...', search: 'Searching files...', command: 'Running command...', test: 'Running tests...',
  edit: 'Editing files...', tool: 'Calling tool...', web: 'Searching the web...',
};

interface Item {
  type: string; id?: string; status?: string; exitCode?: number | null;
  commandActions?: { type: string }[]; changes?: { path?: string }[]; command?: string; server?: string; tool?: string;
}

export interface ActivityOptions {
  /** Timer-driven spinner (live terminals only). Otherwise labels update on events and nothing ticks. */
  animate: boolean;
  color: boolean;
  intervalMs?: number;
  /** Edited paths are shown relative to this directory. */
  cwd?: string;
}

export class Activity {
  private t0 = 0;
  private active = false;
  private paused = false;
  private label = '';
  private detail?: string; // second status row: the command, file or model behind the label
  /** Shown under model-side states (Thinking/Reasoning): e.g. "Model: GPT-6 Luna · Reasoning: Medium". */
  model?: string;
  private frame = 0;
  private timer?: NodeJS.Timeout;
  private seenStarted = new Set<string>();
  private seenDone = new Set<string>();
  private running = 0;
  private group?: { kind: Kind; n: number };
  private committed = 0;
  private hidden = 0;

  constructor(private readonly screen: Screen, private readonly opts: ActivityOptions, private readonly now: () => number = Date.now) {}

  get atLineStart(): boolean { return this.screen.atLineStart; }
  get isActive(): boolean { return this.active; }
  get hasTimer(): boolean { return this.timer !== undefined; }

  // ---- colors -----------------------------------------------------------------------------------
  private paint(code: string, s: string): string { return this.opts.color ? `\x1b[${code}m${s}\x1b[0m` : s; }
  dim(s: string): string { return this.paint('2', s); }
  accent(s: string): string { return this.paint('36', s); }
  paintStatus(kind: 'ok' | 'bad' | 'warn', glyph: string): string { return this.paint(kind === 'ok' ? '32' : kind === 'bad' ? '31' : '33', glyph); }

  // ---- output -----------------------------------------------------------------------------------
  private elapsed(): string { return `${Math.floor((this.now() - this.t0) / 1000)}s`; }

  /** Prefix shown before the label, e.g. the running stage and its model. */
  context = '';

  private draw(): void {
    if (!this.screen.live) return;
    if (!this.active) return this.screen.setStatus(undefined);
    const width = Math.max(10, this.screen.columns - 1) - 2;
    const fit = (s: string, w = width) => (s.length > w ? `${s.slice(0, w - 1)}…` : s);
    // approval: a static row (no animation) while the prompt above waits for an answer
    if (this.paused) return this.screen.setStatus(`  ${this.paint('33', '!')} ${fit(`Waiting for approval · ${this.elapsed()}`, width - 2)}`);
    const glyph = this.opts.animate ? FRAMES[this.frame] : '●';
    const line = fit(`${glyph} ${this.context}${this.label} ${this.elapsed()}`);
    const detail = this.detail ?? (MODEL_SIDE.has(this.label) ? this.model : undefined);
    this.screen.setStatus([`  ${this.paint('36', line[0])}${line.slice(1)}`, ...(detail ? [`    ${this.dim(fit(detail, width - 2))}`] : [])]);
  }

  /** Streamed assistant text. */
  text(s: string): void {
    if (this.group && this.active) { if (!this.screen.atLineStart) this.screen.write('\n'); this.flushGroup(); } // finished tool steps precede the answer
    if (!s) return;
    // breathing room: a blank line between a block of status lines and the answer text
    if (this.last === 'line' && this.screen.atLineStart && s.trim()) this.screen.write('\n');
    if (s.trim()) this.last = 'text';
    this.screen.write(s, { markdown: this.active });
  }

  /** A self-contained block (e.g. an approval prompt): separated from what comes before and after. */
  block(s: string): void {
    if (!this.screen.atLineStart) this.screen.write('\n');
    if (this.last !== 'none') this.screen.write('\n');
    this.screen.write(s.endsWith('\n') ? s : `${s}\n`);
    this.last = 'line';
  }

  /** A permanent one-line notice (e.g. auto-approval) on its own row. */
  notice(line: string): void { this.commit(line); }

  private commit(line: string): void {
    if (!this.screen.atLineStart) this.screen.write('\n');
    if (this.last === 'text') this.screen.write('\n'); // status lines after prose start a new paragraph
    this.screen.write(`${line}\n`);
    this.last = 'line';
  }

  /** What was written last in this turn, for paragraph spacing. */
  private last: 'none' | 'text' | 'line' = 'none';

  // ---- lifecycle ---------------------------------------------------------------------------------
  begin(label: string): void {
    this.stopTimer();
    this.t0 = this.now();
    this.active = true; this.paused = false; this.running = 0; this.group = undefined;
    this.seenStarted.clear(); this.seenDone.clear(); this.committed = 0; this.hidden = 0;
    this.label = label; this.detail = undefined; this.frame = 0;
    this.screen.write(`${this.accent('◆')} Lumina\n`);
    this.screen.prefix = '  ';
    this.last = 'none';
    this.draw();
    this.startTimer();
  }

  /** Animated: spinner frames. Reduced motion / no animation: a static glyph, redrawn once a second for the clock. */
  private startTimer(): void {
    if (!this.screen.live || this.timer) return;
    const tick = this.opts.animate ? () => { this.frame = (this.frame + 1) % FRAMES.length; this.draw(); } : () => this.draw();
    this.timer = setInterval(tick, this.opts.animate ? this.opts.intervalMs ?? 100 : 1000);
    this.timer.unref();
  }

  setLabel(label: string, detail?: string): void {
    if (!this.active || (label === this.label && detail === this.detail)) return;
    this.label = label;
    this.detail = detail;
    this.draw();
  }

  /** A status row without a conversation block (e.g. verification after the turn ended). */
  spin(label: string, detail?: string): void {
    this.stopTimer();
    this.t0 = this.now();
    this.active = true; this.paused = false; this.label = label; this.detail = detail; this.frame = 0;
    this.draw();
    this.startTimer();
  }
  stopSpin(): void { if (!this.active) return; this.stopTimer(); this.active = false; this.draw(); }

  /** Approval required: the animation stops at once; the row says what the turn is waiting for. */
  pause(): void { this.paused = true; this.stopTimer(); this.draw(); }

  resume(): void {
    if (!this.paused) return;
    this.paused = false;
    this.draw();
    if (this.active) this.startTimer();
  }

  /** Terminal resized: the status row is re-fitted. */
  refresh(): void { this.draw(); }

  end(status: EndStatus, detail?: string): void {
    if (!this.active) return; // completion feedback exactly once
    this.stopTimer();
    this.flushGroup();
    this.active = false;
    this.paused = false;
    this.draw();
    if (!this.screen.atLineStart) this.screen.write('\n');
    if (this.last !== 'none') this.screen.write('\n'); // completion stands apart from the answer
    if (this.hidden > 0) this.screen.write(`${this.dim(`… ${this.hidden} more step${this.hidden === 1 ? '' : 's'}`)}\n`);
    const t = this.elapsed();
    const line = status === 'completed' ? `${this.paint('32', '✓')} Completed in ${t}`
      : status === 'failed' ? `${this.paint('31', '✗')} Failed after ${t}`
        : `${this.paint('33', '!')} Cancelled after ${t}`;
    this.screen.write(`${line}\n`);
    if (detail) this.screen.write(`${this.dim(detail.replace(/\s+/g, ' ').slice(0, 200))}\n`);
    this.screen.prefix = '';
    this.screen.write('\n');
    this.screen.resetMarkdown();
    this.last = 'none';
  }

  dispose(): void {
    this.context = '';
    this.stopTimer();
    this.active = false;
    this.screen.setStatus(undefined);
    this.screen.prefix = '';
  }

  private stopTimer(): void {
    if (this.timer) { clearInterval(this.timer); this.timer = undefined; }
  }

  // ---- App Server events → timeline --------------------------------------------------------------
  event(method: string, params: unknown): void {
    if (!this.active) return;
    const item = (params as { item?: Item } | undefined)?.item;
    if (method === 'turn/started') return this.setLabel(this.running ? this.label : 'Thinking...', this.running ? this.detail : undefined);
    if (!item) return;
    if (method === 'item/started') return this.onStarted(item);
    if (method === 'item/completed') return this.onCompleted(item);
  }

  private kindOf(item: Item): Kind | undefined {
    switch (item.type) {
      case 'commandExecution': {
        const a = item.commandActions ?? [];
        if (a.length && a.every((x) => x.type === 'read')) return 'read';
        if (a.length && a.every((x) => x.type === 'search' || x.type === 'listFiles')) return 'search';
        return item.command && TEST_CMD.test(unwrap(item.command)) ? 'test' : 'command';
      }
      case 'fileChange': return 'edit';
      case 'mcpToolCall': case 'dynamicToolCall': return 'tool';
      case 'webSearch': return 'web';
      default: return undefined;
    }
  }

  private onStarted(item: Item): void {
    const key = item.id ?? '';
    if (key && this.seenStarted.has(key)) return;
    if (key) this.seenStarted.add(key);
    const kind = this.kindOf(item);
    if (kind) {
      if (this.group && this.group.kind !== kind) this.flushGroup();
      this.group ??= { kind, n: 0 };
      this.running++;
      return this.setLabel(LABEL[kind], this.detailOf(kind, item));
    }
    if (item.type === 'reasoning') { this.flushGroup(); this.setLabel('Reasoning...'); }
    else if (item.type === 'plan') this.setLabel('Planning...');
    else if (item.type === 'contextCompaction') this.setLabel('Compacting context...');
  }

  /** What the running step works on, straight from the event: the command, the edited files, the tool. */
  private detailOf(kind: Kind, item: Item): string | undefined {
    if (item.type === 'commandExecution') return item.command ? unwrap(item.command).replace(/\s+/g, ' ').trim() : undefined;
    if (kind === 'edit') {
      const files = (item.changes ?? []).map((c) => c.path).filter((p): p is string => Boolean(p))
        .map((p) => (this.opts.cwd && path.isAbsolute(p) && !path.relative(this.opts.cwd, p).startsWith('..') ? path.relative(this.opts.cwd, p) : p));
      return files.length ? `${files[0]}${files.length > 1 ? ` (+${files.length - 1} more)` : ''}` : undefined;
    }
    if (kind === 'tool' && item.tool) return item.server ? `${item.server} › ${item.tool}` : item.tool;
    return undefined;
  }

  private onCompleted(item: Item): void {
    const key = item.id ?? '';
    if (key && this.seenDone.has(key)) return;
    if (key) this.seenDone.add(key);
    const kind = this.kindOf(item);
    if (kind) {
      this.running = Math.max(0, this.running - 1);
      const failed = item.status === 'failed' || item.status === 'declined' || (typeof item.exitCode === 'number' && item.exitCode !== 0);
      if (failed) {
        this.flushGroup();
        const what = kind === 'edit' ? 'Edit' : kind === 'tool' ? 'Tool call' : kind === 'web' ? 'Search' : kind === 'test' ? 'Tests' : 'Command';
        const declined = item.status === 'declined';
        this.commit(declined ? `${this.paint('33', '!')} ${what} declined` : `${this.paint('31', '✗')} ${what} failed${typeof item.exitCode === 'number' ? ` (exit ${item.exitCode})` : ''}`);
      } else if (this.group) {
        this.group.n += kind === 'edit' ? Math.max(1, item.changes?.length ?? 1)
          : kind === 'read' ? Math.max(1, (item.commandActions ?? []).filter((a) => a.type === 'read').length) : 1;
      }
      if (this.running === 0) this.setLabel('Thinking...');
    } else if (item.type === 'reasoning') this.setLabel('Thinking...');
    else if (item.type === 'agentMessage') { this.flushGroup(); this.setLabel('Finalizing...'); }
  }

  private flushGroup(): void {
    const g = this.group;
    this.group = undefined;
    if (!g || g.n === 0) return;
    const s = g.n === 1 ? '' : 's';
    const text = { read: `Read ${g.n} file${s}`, search: `Searched ${g.n} time${s}`, command: `Ran ${g.n} command${s}`, test: `Ran tests${g.n > 1 ? ` (${g.n} runs)` : ''}`, edit: `Edited ${g.n} file${s}`, tool: `Used ${g.n} tool call${s}`, web: 'Searched the web' }[g.kind];
    if (this.committed >= MAX_COMMITTED) { this.hidden++; return; }
    this.committed++;
    this.commit(`${this.paint('32', '✓')} ${text}`);
  }
}

private draw(): void {
  if (!this.screen.live) return;
  if (!this.active) return this.screen.setStatus(undefined);
  const width = Math.max(10, this.screen.columns - 1) - 2;
  const fit = (s: string, w = width) => (s.length > w ? `${s.slice(0, w - 1)}…` : s);
  // approval: a static row (no animation) while the prompt above waits for an answer
  if (this.paused) return this.screen.setStatus(`  ${this.paint('33', '!')} ${fit(`Waiting for approval · ${this.elapsed()}`, width - 2)}`);
  const glyph = this.opts.animate ? FRAMES[this.frame] : '●';
  const line = fit(`${glyph} ${this.context}${this.label} ${this.elapsed()}`);
  const detail = this.detail ?? (MODEL_SIDE.has(this.label) ? this.model : undefined);
  this.screen.setStatus([`  ${this.paint('36', line[0])}${line.slice(1)}`, ...(detail ? [`    ${this.dim(fit(detail, width - 2))}`] : [])]);
}

text(s: string): void {
  if (this.group && this.active) { if (!this.screen.atLineStart) this.screen.write('\n'); this.flushGroup(); } // finished tool steps precede the answer
  if (!s) return;
  // breathing room: a blank line between a block of status lines and the answer text
  if (this.last === 'line' && this.screen.atLineStart && s.trim()) this.screen.write('\n');
  if (s.trim()) this.last = 'text';
  this.screen.write(s, { markdown: this.active });
}

block(s: string): void {
  if (!this.screen.atLineStart) this.screen.write('\n');
  if (this.last !== 'none') this.screen.write('\n');
  this.screen.write(s.endsWith('\n') ? s : `${s}\n`);
  this.last = 'line';
}

private commit(line: string): void {
  if (!this.screen.atLineStart) this.screen.write('\n');
  if (this.last === 'text') this.screen.write('\n'); // status lines after prose start a new paragraph
  this.screen.write(`${line}\n`);
  this.last = 'line';
}

begin(label: string): void {
  this.stopTimer();
  this.t0 = this.now();
  this.active = true; this.paused = false; this.running = 0; this.group = undefined;
  this.seenStarted.clear(); this.seenDone.clear(); this.committed = 0; this.hidden = 0;
  this.label = label; this.detail = undefined; this.frame = 0;
  this.screen.write(`${this.accent('◆')} Lumina\n`);
  this.screen.prefix = '  ';
  this.last = 'none';
  this.draw();
  this.startTimer();
}

private startTimer(): void {
  if (!this.screen.live || this.timer) return;
  const tick = this.opts.animate ? () => { this.frame = (this.frame + 1) % FRAMES.length; this.draw(); } : () => this.draw();
  this.timer = setInterval(tick, this.opts.animate ? this.opts.intervalMs ?? 100 : 1000);
  this.timer.unref();
}

setLabel(label: string, detail?: string): void {
  if (!this.active || (label === this.label && detail === this.detail)) return;
  this.label = label;
  this.detail = detail;
  this.draw();
}

spin(label: string, detail?: string): void {
  this.stopTimer();
  this.t0 = this.now();
  this.active = true; this.paused = false; this.label = label; this.detail = detail; this.frame = 0;
  this.draw();
  this.startTimer();
}

resume(): void {
  if (!this.paused) return;
  this.paused = false;
  this.draw();
  if (this.active) this.startTimer();
}

end(status: EndStatus, detail?: string): void {
  if (!this.active) return; // completion feedback exactly once
  this.stopTimer();
  this.flushGroup();
  this.active = false;
  this.paused = false;
  this.draw();
  if (!this.screen.atLineStart) this.screen.write('\n');
  if (this.last !== 'none') this.screen.write('\n'); // completion stands apart from the answer
  if (this.hidden > 0) this.screen.write(`${this.dim(`… ${this.hidden} more step${this.hidden === 1 ? '' : 's'}`)}\n`);
  const t = this.elapsed();
  const line = status === 'completed' ? `${this.paint('32', '✓')} Completed in ${t}`
    : status === 'failed' ? `${this.paint('31', '✗')} Failed after ${t}`
      : `${this.paint('33', '!')} Cancelled after ${t}`;
  this.screen.write(`${line}\n`);
  if (detail) this.screen.write(`${this.dim(detail.replace(/\s+/g, ' ').slice(0, 200))}\n`);
  this.screen.prefix = '';
  this.screen.write('\n');
  this.screen.resetMarkdown();
  this.last = 'none';
}

const line = status === 'completed' ? `${this.paint('32', '✓')} Completed in ${t}`
  : status === 'failed' ? `${this.paint('31', '✗')} Failed after ${t}`
    : `${this.paint('33', '!')} Cancelled after ${t}`;

dispose(): void {
  this.context = '';
  this.stopTimer();
  this.active = false;
  this.screen.setStatus(undefined);
  this.screen.prefix = '';
}

private stopTimer(): void {
  if (this.timer) { clearInterval(this.timer); this.timer = undefined; }
}

event(method: string, params: unknown): void {
  if (!this.active) return;
  const item = (params as { item?: Item } | undefined)?.item;
  if (method === 'turn/started') return this.setLabel(this.running ? this.label : 'Thinking...', this.running ? this.detail : undefined);
  if (!item) return;
  if (method === 'item/started') return this.onStarted(item);
  if (method === 'item/completed') return this.onCompleted(item);
}

private kindOf(item: Item): Kind | undefined {
  switch (item.type) {
    case 'commandExecution': {
      const a = item.commandActions ?? [];
      if (a.length && a.every((x) => x.type === 'read')) return 'read';
      if (a.length && a.every((x) => x.type === 'search' || x.type === 'listFiles')) return 'search';
      return item.command && TEST_CMD.test(unwrap(item.command)) ? 'test' : 'command';
    }
    case 'fileChange': return 'edit';
    case 'mcpToolCall': case 'dynamicToolCall': return 'tool';
    case 'webSearch': return 'web';
    default: return undefined;
  }
}

private onStarted(item: Item): void {
  const key = item.id ?? '';
  if (key && this.seenStarted.has(key)) return;
  if (key) this.seenStarted.add(key);
  const kind = this.kindOf(item);
  if (kind) {
    if (this.group && this.group.kind !== kind) this.flushGroup();
    this.group ??= { kind, n: 0 };
    this.running++;
    return this.setLabel(LABEL[kind], this.detailOf(kind, item));
  }
  if (item.type === 'reasoning') { this.flushGroup(); this.setLabel('Reasoning...'); }
  else if (item.type === 'plan') this.setLabel('Planning...');
  else if (item.type === 'contextCompaction') this.setLabel('Compacting context...');
}

private detailOf(kind: Kind, item: Item): string | undefined {
  if (item.type === 'commandExecution') return item.command ? unwrap(item.command).replace(/\s+/g, ' ').trim() : undefined;
  if (kind === 'edit') {
    const files = (item.changes ?? []).map((c) => c.path).filter((p): p is string => Boolean(p))
      .map((p) => (this.opts.cwd && path.isAbsolute(p) && !path.relative(this.opts.cwd, p).startsWith('..') ? path.relative(this.opts.cwd, p) : p));
    return files.length ? `${files[0]}${files.length > 1 ? ` (+${files.length - 1} more)` : ''}` : undefined;
  }
  if (kind === 'tool' && item.tool) return item.server ? `${item.server} › ${item.tool}` : item.tool;
  return undefined;
}

private onCompleted(item: Item): void {
  const key = item.id ?? '';
  if (key && this.seenDone.has(key)) return;
  if (key) this.seenDone.add(key);
  const kind = this.kindOf(item);
  if (kind) {
    this.running = Math.max(0, this.running - 1);
    const failed = item.status === 'failed' || item.status === 'declined' || (typeof item.exitCode === 'number' && item.exitCode !== 0);
    if (failed) {
      this.flushGroup();
      const what = kind === 'edit' ? 'Edit' : kind === 'tool' ? 'Tool call' : kind === 'web' ? 'Search' : kind === 'test' ? 'Tests' : 'Command';
      const declined = item.status === 'declined';
      this.commit(declined ? `${this.paint('33', '!')} ${what} declined` : `${this.paint('31', '✗')} ${what} failed${typeof item.exitCode === 'number' ? ` (exit ${item.exitCode})` : ''}`);
    } else if (this.group) {
      this.group.n += kind === 'edit' ? Math.max(1, item.changes?.length ?? 1)
        : kind === 'read' ? Math.max(1, (item.commandActions ?? []).filter((a) => a.type === 'read').length) : 1;
    }
    if (this.running === 0) this.setLabel('Thinking...');
  } else if (item.type === 'reasoning') this.setLabel('Thinking...');
  else if (item.type === 'agentMessage') { this.flushGroup(); this.setLabel('Finalizing...'); }
}

private flushGroup(): void {
  const g = this.group;
  this.group = undefined;
  if (!g || g.n === 0) return;
  const s = g.n === 1 ? '' : 's';
  const text = { read: `Read ${g.n} file${s}`, search: `Searched ${g.n} time${s}`, command: `Ran ${g.n} command${s}`, test: `Ran tests${g.n > 1 ? ` (${g.n} runs)` : ''}`, edit: `Edited ${g.n} file${s}`, tool: `Used ${g.n} tool call${s}`, web: 'Searched the web' }[g.kind];
  if (this.committed >= MAX_COMMITTED) { this.hidden++; return; }
  this.committed++;
  this.commit(`${this.paint('32', '✓')} ${text}`);
}

export class Chat {
  threadId?: string;
  model?: string;
  busy = false;
  /** Latest token usage reported by the App Server for the current thread (undefined until a turn reports it). */
  usage?: import('../usage.js').SessionUsage;
  private turnId?: string;
  private approvals = new Map<string, Promise<Decision>>();

  constructor(private client: AppClient, private readonly opts: { cwd: string; onDelta: (text: string) => void; onEvent?: (method: string, params: unknown) => void; onApproval?: (r: ApprovalRequest) => Promise<Decision>; policy?: Policy }) {
    this.attach(client);
  }

  /** (Re)binds to an App Server client, e.g. after a reconnect. */
  attach(client: AppClient): void {
    this.client = client;
    client.onServerRequest((method, params) => this.onServerRequest(method, params));
  }

  /** Approval requests for this thread go to the UI; anything else, or no UI, is declined (safe default). */
  private async onServerRequest(method: string, params: unknown): Promise<unknown> {
    const p = params as { threadId?: string; itemId?: string; approvalId?: string | null; networkApprovalContext?: unknown; command?: string | null; cwd?: string | null; reason?: string | null; grantRoot?: string | null };
    if (p?.threadId !== this.threadId && (!this.activeThread || p?.threadId !== this.activeThread)) throw new Error('Request for an unknown conversation');
    if (method === 'mcpServer/elicitation/request') return this.onMcpElicitation(params as McpElicitation);
    if (method !== 'item/commandExecution/requestApproval' && method !== 'item/fileChange/requestApproval') throw new Error(`Unsupported request: ${method}`);
    const command = method === 'item/commandExecution/requestApproval';
    const detail = [p.cwd && command ? `in ${p.cwd}` : '', p.grantRoot ? `grants write access to ${p.grantRoot}` : '', p.reason ?? ''].filter(Boolean).join(' · ');
    const ask = (): Promise<Decision> => this.opts.onApproval
      ? this.opts.onApproval({ kind: command ? 'command' : 'fileChange', summary: command ? (p.command ?? 'command') : 'apply file changes', detail, command: command ? (p.command ?? undefined) : undefined, cwd: p.cwd, network: Boolean(p.networkApprovalContext), reason: p.reason ?? undefined })
      : Promise.resolve('decline');
    // A repeated request for the same item gets the same answer, never a second prompt or response.
    const key = p.itemId ? `${method}:${p.itemId}:${p.approvalId ?? ''}` : '';
    let pending = key ? this.approvals.get(key) : undefined;
    if (!pending) { pending = ask(); if (key) this.approvals.set(key, pending); }
    const decision = await pending;
    return { decision };
  }

  /**
   * MCP tool-call approvals arrive as elicitations tagged `codex_approval_kind: mcp_tool_call`. They always go to the user
   * (never auto-approved: tools may write to external systems). Any other elicitation (forms, URLs) is unsupported → error.
   */
  private async onMcpElicitation(p: McpElicitation): Promise<unknown> {
    if (p._meta?.codex_approval_kind !== 'mcp_tool_call') throw new Error('Unsupported MCP elicitation');
    const tool = /tool "([^"]+)"/.exec(p.message)?.[1] ?? 'tool';
    const args = (p._meta.tool_params_display ?? []).map((d) => `${d.display_name ?? d.name}=${String(d.value).replace(/\s+/g, ' ').slice(0, 60)}`).join(', ');
    const decision = this.opts.onApproval
      ? await this.opts.onApproval({ kind: 'mcpTool', summary: `${p.serverName} › ${tool}`, detail: args.slice(0, 200), server: p.serverName, tool })
      : 'decline';
    const action = decision === 'accept' || decision === 'acceptForSession' ? 'accept' : decision === 'cancel' ? 'cancel' : 'decline';
    // "for session" asks Codex to remember the approval (one of the persist modes offered in _meta)
    const meta = decision === 'acceptForSession' && p._meta.persist?.includes('session') ? { persist: 'session' } : null;
    return { action, content: null, _meta: meta };
  }

  /** Interrupts the running turn. Resolves false when no turn is active. */
  async interrupt(): Promise<boolean> {
    const thread = this.activeThread ?? this.threadId;
    if (!this.busy || !thread || !this.turnId) return false;
    await this.client.request('turn/interrupt', { threadId: thread, turnId: this.turnId });
    return true;
  }

  private async ensureThread(): Promise<string> {
    if (this.threadId) return this.threadId;
    const res = await this.client.request<{ thread: { id: string }; model: string; sandbox?: unknown }>('thread/start', {
      cwd: this.opts.cwd, ...(this.opts.policy ?? DEFAULT_POLICY),
    });
    this.model = res.model;
    this.sandbox = res.sandbox;
    return (this.threadId = res.thread.id);
  }

  /** Starts a fresh conversation on the next send (/new). */
  reset(): void {
    if (this.busy) throw new Error('A turn is running');
    this.threadId = undefined;
    this.usage = undefined;
    this.sandboxOverridden = false;
  }

  /** Recent threads for this cwd, newest first. Codex persists them; nothing is stored by Lumina. */
  async list(limit = 10): Promise<ThreadSummary[]> {
    const res = await this.client.request<{ data: { id: string; preview?: string; name?: string | null }[] }>('thread/list', {
      cwd: this.opts.cwd, limit, sortKey: 'updated_at',
    });
    return res.data.map((t) => ({ id: t.id, preview: (t.name || t.preview || '').replace(/\s+/g, ' ').slice(0, 60) }));
  }

  /** One page of saved conversations for this cwd, newest activity first (metadata only, no turns). */
  async listPage(opts: { limit?: number; cursor?: string | null } = {}): Promise<{ items: { id: string; title: string; updatedAt: number }[]; nextCursor: string | null }> {
    const res = await this.client.request<{ data: { id: string; preview?: string; name?: string | null; updatedAt?: number }[]; nextCursor?: string | null }>('thread/list', {
      cwd: this.opts.cwd, limit: opts.limit ?? 50, sortKey: 'updated_at', sortDirection: 'desc', ...(opts.cursor ? { cursor: opts.cursor } : {}),
    });
    return {
      items: res.data.map((t) => ({ id: t.id, updatedAt: t.updatedAt ?? 0, title: (t.name || (t.preview ?? '').split('\n').find((l) => l.trim()) || '(untitled conversation)').replace(/\s+/g, ' ').trim().slice(0, 200) })),
      nextCursor: res.nextCursor ?? null,
    };
  }

  /** Persisted turns of a thread (server-side read, no model call). Empty when unavailable. */
  async readTurns(id: string): Promise<import('./history.js').HistoryTurn[]> {
    const res = await this.client.request<{ thread?: { turns?: import('./history.js').HistoryTurn[] } }>('thread/read', { threadId: id, includeTurns: true });
    return res?.thread?.turns ?? [];
  }

  /** Re-attaches to a persisted thread; the server restores the full conversation context. */
  async resume(id: string): Promise<void> {
    if (this.busy) throw new Error('A turn is running');
    const res = await this.client.request<{ thread: { id: string }; model: string; sandbox?: unknown }>('thread/resume', {
      threadId: id, cwd: this.opts.cwd, ...(this.opts.policy ?? DEFAULT_POLICY), excludeTurns: true,
    });
    this.threadId = res.thread.id;
    this.model = res.model;
    this.sandbox = res.sandbox;
    this.sandboxOverridden = false;
    this.usage = undefined;
  }

  /** The thread's own sandbox policy (from thread/start|resume), restored after a read-only turn. */
  private sandbox?: unknown;
  private sandboxOverridden = false;

  /** Context carried into the next main-thread turn (e.g. results of a stage that ran on an isolated thread). */
  private carry?: string;
  queueContext(note: string): void { this.carry = this.carry ? `${this.carry}\n${note}` : note; }

  /** Thread of the turn currently running (main or isolated); approvals and interrupts target it. */
  private activeThread?: string;
  /** Last cumulative usage per thread, so a turn's own usage is the difference (no double counting). */
  private totals = new Map<string, TokenBreakdown>();

  /** Main-thread context size from the last provider report (tokens of the last request), if known. */
  contextTokens(): { used: number; window: number | null } | undefined {
    return this.usage?.last ? { used: this.usage.last.totalTokens, window: this.usage.modelContextWindow } : undefined;
  }

  /** Asks Codex to compact the main thread and waits for `thread/compacted` (bounded). Returns false when it did not happen. */
  /** Provider-reported usage of the last compaction, when Codex reported any (undefined = not reported). */
  lastCompactionUsage?: TokenBreakdown;

  async compact(timeoutMs = 120000): Promise<boolean> {
    const id = this.threadId;
    if (!id || this.busy) return false;
    this.busy = true;
    let off: (() => void) | undefined;
    try {
      this.lastCompactionUsage = undefined;
      const before = this.totals.get(id);
      const done = new Promise<boolean>((resolve) => {
        const t = setTimeout(() => resolve(false), timeoutMs);
        t.unref?.();
        off = this.client.onNotification((m, p) => {
          const q = p as { threadId?: string; tokenUsage?: import('../usage.js').SessionUsage };
          if (q?.threadId !== id) return;
          // the compaction's own cost, only if Codex reports usage for it
          if (m === 'thread/tokenUsage/updated' && q.tokenUsage) { const total = q.tokenUsage.total as TokenBreakdown; this.lastCompactionUsage = diffUsage(total, before); this.totals.set(id, total); this.usage = q.tokenUsage; }
          if (m === 'thread/compacted') { clearTimeout(t); resolve(true); }
        });
      });
      await this.client.request('thread/compact/start', { threadId: id });
      return await done;
    } finally { off?.(); this.busy = false; }
  }

  /**
   * Runs one turn. `isolated` starts a fresh, ephemeral thread (same cwd, sandbox and approval policy) so the turn does
   * not carry the main conversation's history; the main thread is left untouched.
   */
  async send(text: string, sel: Selection = {}, skills: { name: string; path: string }[] = [], opts: { isolated?: boolean; images?: string[]; readOnly?: boolean } = {}): Promise<TurnResult> {
    if (this.busy) throw new Error('A turn is already running');
    this.busy = true;
    let off: (() => void) | undefined;
    try {
      const threadId = opts.isolated
        ? (await this.client.request<{ thread: { id: string } }>('thread/start', { cwd: this.opts.cwd, ...(this.opts.policy ?? DEFAULT_POLICY), ephemeral: true })).thread.id
        : await this.ensureThread();
      this.activeThread = threadId;
      // per-turn sandbox (persists in Codex for later turns): read-only for understanding, then restore the thread's own
      let sandboxOverride = {};
      if (opts.readOnly) { sandboxOverride = { sandboxPolicy: { type: 'readOnly', networkAccess: false } }; if (!opts.isolated) this.sandboxOverridden = true; }
      else if (this.sandboxOverridden && !opts.isolated && this.sandbox) { sandboxOverride = { sandboxPolicy: this.sandbox }; this.sandboxOverridden = false; }
      const before = this.totals.get(threadId);
      if (!opts.isolated && this.carry) { text = `${this.carry}\n\n${text}`; this.carry = undefined; }
      const done = new Promise<TurnResult>((resolve) => {
        let lastError: string | undefined;
        let total: TokenBreakdown | undefined;
        const items: TurnItem[] = [];
        this.client.onClose((e) => resolve({ status: 'failed', error: e.message }));
        off = this.client.onNotification((method, params) => {
          const p = params as { item?: { type: string; status?: string; exitCode?: number | null; command?: string; changes?: { path?: string }[]; text?: string; tool?: string; commandActions?: { type: string; path?: string | null }[]; cwd?: string; durationMs?: number | null }; threadId?: string; delta?: string; error?: { message?: string }; willRetry?: boolean; turn?: { id?: string; status: TurnResult['status']; error?: { message?: string } | null } };
          if (p?.threadId !== threadId) return;
          this.opts.onEvent?.(method, params);
          if (method === 'item/agentMessage/delta' && p.delta) this.opts.onDelta(p.delta);
          else if (method === 'error' && !p.willRetry) lastError = p.error?.message;
          else if (method === 'thread/tokenUsage/updated') {
            const u = (params as { tokenUsage: import('../usage.js').SessionUsage }).tokenUsage;
            total = u.total as TokenBreakdown;
            this.totals.set(threadId, total);
            if (!opts.isolated) this.usage = u;
          }
          else if (method === 'turn/started' && p.turn?.id) this.turnId = p.turn.id;
          else if (method === 'item/completed' && p.item) {
            const it = p.item;
            items.push({ type: it.type, status: it.status, exitCode: it.exitCode, command: it.command?.slice(0, 300), files: it.changes?.map((c) => c.path ?? '').filter(Boolean), text: it.type === 'agentMessage' ? it.text?.slice(-2000) : undefined, tool: it.tool, ...(it.type === 'commandExecution' ? { actions: (it.commandActions ?? []).map((a) => a.type), cwd: it.cwd, durationMs: it.durationMs ?? undefined } : {}), ...(it.commandActions?.some((a) => a.type === 'read' && a.path) ? { reads: it.commandActions.filter((a) => a.type === 'read' && a.path).map((a) => a.path!) } : {}) });
          }
          else if (method === 'turn/completed' && p.turn) resolve({ status: p.turn.status, error: p.turn.error?.message ?? lastError, items, usage: total ? diffUsage(total, before) : undefined });
        });
      });
      const started = await this.client.request<{ turn?: { id?: string } }>('turn/start', {
        // explicit `$skill` invocations are passed to Codex as native skill items; Codex loads the SKILL.md itself
        // pasted images go as native localImage items (Codex reads the file); skills as native skill items
        threadId, input: [{ type: 'text', text, text_elements: [] }, ...(opts.images ?? []).map((p) => ({ type: 'localImage', path: p })), ...skills.map((k) => ({ type: 'skill', name: k.name, path: k.path }))],
        ...(sel.model ? { model: sel.model } : {}), ...(sel.effort ? { effort: sel.effort } : {}),
        ...sandboxOverride,
      });
      this.turnId ??= started?.turn?.id;
      return await done;
    } finally {
      this.turnId = undefined;
      this.activeThread = undefined;
      this.approvals.clear();
      off?.();
      this.busy = false;
    }
  }
}

