const run = (cmd: string, args: string[], text: string) => new Promise<boolean>((resolve) => {
  try {
    const p = spawn(cmd, args, { stdio: ['pipe', 'ignore', 'ignore'] });
    p.on('error', () => resolve(false));
    p.on('close', (code) => resolve(code === 0));
    p.stdin?.on('error', () => undefined);
    p.stdin?.end(text);
  } catch { resolve(false); }
});

