    ...this.getHeaders(),
    ...options.headers,
  };

  const response = await fetch(url, { ...options, headers });

  if (!response.ok) {
    let errorData;
    try {
      errorData = await response.json();
    } catch {
      errorData = response.statusText;
    }
    throw new Error(`GitHub API Error (${response.status}): ${JSON.stringify(errorData)}`);
  }

  return response.text();
}

