    const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/).slice(startLine - 1, endLine);
    return { content: [{ type: 'text', text: JSON.stringify({ file, startLine, endLine, content: lines.join('\n') }, null, 2) }] };
  });
}

