export interface CacheStats {
  size: number;
  hits: number;
  misses: number;
  evictions: number;
}

interface Entry<Value> {
  value: Value;
  expiresAt: number;
  active: number;
  evicted: boolean;
}

export class LruTtlCache<Key, Value> {
  private readonly entries = new Map<Key, Entry<Value>>();
  private hits = 0;
  private misses = 0;
  private evictions = 0;

  constructor(
    private readonly maxEntries: number,
    private readonly ttlMs: number,
    private readonly onEvict: (value: Value) => void,
  ) {}

  getOrCreate(key: Key, create: () => Value): Value {
    return this.getEntry(key, create).value;
  }

  acquire(key: Key, create: () => Value): { value: Value; release(): void } {
    const entry = this.getEntry(key, create);
    entry.active += 1;
    let released = false;
    return {
      value: entry.value,
      release: () => {
        if (released) return;
        released = true;
        entry.active -= 1;
        if (entry.evicted && entry.active === 0) this.dispose(entry);
      },
    };
  }

  values(): Value[] {
    return [...this.entries.values()].map((entry) => entry.value);
  }

  clear(): Value[] {
    const values = this.values();
    this.entries.clear();
    return values;
  }

  stats(): CacheStats {
    this.expire();
    return { size: this.entries.size, hits: this.hits, misses: this.misses, evictions: this.evictions };
  }

  private expire(): void {
    const now = Date.now();
    for (const [key, entry] of this.entries) {
      if (entry.expiresAt <= now) this.evict(key, entry);
    }
  }

  private evictOldest(): void {
    const first = this.entries.entries().next().value as [Key, Entry<Value>] | undefined;
    if (first) this.evict(first[0], first[1]);
  }

  private evict(key: Key, entry: Entry<Value>): void {
    this.entries.delete(key);
    this.evictions += 1;
    entry.evicted = true;
    if (entry.active === 0) this.dispose(entry);
  }

  private getEntry(key: Key, create: () => Value): Entry<Value> {
    this.expire();
    const existing = this.entries.get(key);
    if (existing) {
      this.hits += 1;
      this.entries.delete(key);
      existing.expiresAt = Date.now() + this.ttlMs;
      this.entries.set(key, existing);
      return existing;
    }

    this.misses += 1;
    const entry: Entry<Value> = {
      value: create(),
      expiresAt: Date.now() + this.ttlMs,
      active: 0,
      evicted: false,
    };
    this.entries.set(key, entry);
    while (this.entries.size > this.maxEntries) this.evictOldest();
    return entry;
  }

  private dispose(entry: Entry<Value>): void {
    if (!entry.evicted) return;
    entry.evicted = false;
    this.onEvict(entry.value);
  }
}

constructor(
  private readonly maxEntries: number,
  private readonly ttlMs: number,
  private readonly onEvict: (value: Value) => void,
) {}

getOrCreate(key: Key, create: () => Value): Value {
  return this.getEntry(key, create).value;
}

acquire(key: Key, create: () => Value): { value: Value; release(): void } {
  const entry = this.getEntry(key, create);
  entry.active += 1;
  let released = false;
  return {
    value: entry.value,
    release: () => {
      if (released) return;
      released = true;
      entry.active -= 1;
      if (entry.evicted && entry.active === 0) this.dispose(entry);
    },
  };
}

release: () => {
  if (released) return;
  released = true;
  entry.active -= 1;
  if (entry.evicted && entry.active === 0) this.dispose(entry);
},

values(): Value[] {
  return [...this.entries.values()].map((entry) => entry.value);
}

clear(): Value[] {
  const values = this.values();
  this.entries.clear();
  return values;
}

stats(): CacheStats {
  this.expire();
  return { size: this.entries.size, hits: this.hits, misses: this.misses, evictions: this.evictions };
}

private expire(): void {
  const now = Date.now();
  for (const [key, entry] of this.entries) {
    if (entry.expiresAt <= now) this.evict(key, entry);
  }
}

private evictOldest(): void {
  const first = this.entries.entries().next().value as [Key, Entry<Value>] | undefined;
  if (first) this.evict(first[0], first[1]);
}

private evict(key: Key, entry: Entry<Value>): void {
  this.entries.delete(key);
  this.evictions += 1;
  entry.evicted = true;
  if (entry.active === 0) this.dispose(entry);
}

private getEntry(key: Key, create: () => Value): Entry<Value> {
  this.expire();
  const existing = this.entries.get(key);
  if (existing) {
    this.hits += 1;
    this.entries.delete(key);
    existing.expiresAt = Date.now() + this.ttlMs;
    this.entries.set(key, existing);
    return existing;
  }

  this.misses += 1;
  const entry: Entry<Value> = {
    value: create(),
    expiresAt: Date.now() + this.ttlMs,
    active: 0,
    evicted: false,
  };
  this.entries.set(key, entry);
  while (this.entries.size > this.maxEntries) this.evictOldest();
  return entry;
}

const entry: Entry<Value> = {
  value: create(),
  expiresAt: Date.now() + this.ttlMs,
  active: 0,
  evicted: false,
};

private dispose(entry: Entry<Value>): void {
  if (!entry.evicted) return;
  entry.evicted = false;
  this.onEvict(entry.value);
}

export function applyPromptArgsPatch(server: McpServer): void {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  type RegisteredPrompt = {
    enabled: boolean;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    argsSchema?: any;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    callback: (...args: any[]) => unknown;
  };

  server.server.setRequestHandler(
    GetPromptRequestSchema,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async (request, extra): Promise<any> => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const registeredPrompts = (server as any)._registeredPrompts as Record<
        string,
        RegisteredPrompt
      >;

      const prompt = registeredPrompts[request.params.name];
      if (!prompt) {
        throw new McpError(ErrorCode.InvalidParams, `Prompt ${request.params.name} not found`);
      }
      if (!prompt.enabled) {
        throw new McpError(ErrorCode.InvalidParams, `Prompt ${request.params.name} disabled`);
      }

      if (prompt.argsSchema) {
        const argsObj = normalizeObjectSchema(prompt.argsSchema);

        // KEY FIX: normalize undefined → {} so Zod accepts optional-only schemas
        // when hosts omit the `arguments` field entirely.
        const rawArgs = request.params.arguments ?? {};

        const parseResult = await safeParseAsync(argsObj!, rawArgs);
        if (!parseResult.success) {
          const error = 'error' in parseResult ? parseResult.error : 'Unknown error';
          const errorMessage = getParseErrorMessage(error);
          throw new McpError(
            ErrorCode.InvalidParams,
            `Invalid arguments for prompt ${request.params.name}: ${errorMessage}`,
          );
        }

        return await Promise.resolve(prompt.callback(parseResult.data, extra));
      }

      return await Promise.resolve(prompt.callback(extra));
    },
  );
}

type RegisteredPrompt = {
  enabled: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  argsSchema?: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  callback: (...args: any[]) => unknown;
};

async (request, extra): Promise<any> => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const registeredPrompts = (server as any)._registeredPrompts as Record<
    string,
    RegisteredPrompt
  >;

  const prompt = registeredPrompts[request.params.name];
  if (!prompt) {
    throw new McpError(ErrorCode.InvalidParams, `Prompt ${request.params.name} not found`);
  }
  if (!prompt.enabled) {
    throw new McpError(ErrorCode.InvalidParams, `Prompt ${request.params.name} disabled`);
  }

  if (prompt.argsSchema) {
    const argsObj = normalizeObjectSchema(prompt.argsSchema);

    // KEY FIX: normalize undefined → {} so Zod accepts optional-only schemas
    // when hosts omit the `arguments` field entirely.
    const rawArgs = request.params.arguments ?? {};

    const parseResult = await safeParseAsync(argsObj!, rawArgs);
    if (!parseResult.success) {
      const error = 'error' in parseResult ? parseResult.error : 'Unknown error';
      const errorMessage = getParseErrorMessage(error);
      throw new McpError(
        ErrorCode.InvalidParams,
        `Invalid arguments for prompt ${request.params.name}: ${errorMessage}`,
      );
    }

    return await Promise.resolve(prompt.callback(parseResult.data, extra));
  }

  return await Promise.resolve(prompt.callback(extra));
},

function createWorkspace(): { homeDir: string; projectDir: string } {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'lumina-installer-'));
  temporaryRoots.push(root);
  const homeDir = path.join(root, 'home');
  const projectDir = path.join(root, 'project');
  fs.mkdirSync(homeDir, { recursive: true });
  fs.mkdirSync(projectDir, { recursive: true });
  return { homeDir, projectDir };
}

afterEach(() => {
  for (const root of temporaryRoots.splice(0)) {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

