  id: string;
  total: number;
}
');
  w('src/orders/repository.ts', "import type { Order } from './types';
export class OrderRepository { find(id: string): Order | undefined { return undefined; } }
");
  w('src/orders/service.ts', "import { OrderRepository } from './repository';
import type { Order } from './types';
export class OrderService {
  repo = new OrderRepository();
  get(id: string): Order | undefined { return this.repo.find(id); }
}
