    [t, 1, "Error: Cannot find module 'vitest'", 'missing dependency'],
    [t, 1, 'ModuleNotFoundError: No module named "fastapi"', 'missing dependency'],
    [t, 1, 'connect ECONNREFUSED 127.0.0.1:5432', 'external service unavailable'],
