    const api = b.relationships.find((r) => r.kind === 'api')!;
    expect(api).toMatchObject({ from: 'frontend', to: 'backend', status: 'verified', detail: '2 API calls to backend' });
    const t = await b.impact('GET /api/v1/orders');
